# Generated by curly apply. Deterministic brace-expansion helper.
# A value with no `{...}` groups always expands to exactly itself, so
# callers that never pass brace syntax see unchanged behavior.
from __future__ import annotations
from itertools import product
from typing import List


class BraceExpandError(ValueError):
    pass


def _split_top_level(text: str, sep: str = ",") -> List[str]:
    parts = []
    depth = 0
    start = 0
    for i, c in enumerate(text):
        if c == "{":
            depth += 1
        elif c == "}":
            if depth == 0:
                raise BraceExpandError("unmatched '}' while splitting brace alternatives")
            depth -= 1
        elif c == sep and depth == 0:
            parts.append(text[start:i])
            start = i + 1
    if depth != 0:
        raise BraceExpandError("unmatched '{' while splitting brace alternatives")
    parts.append(text[start:])
    return parts


def _parse_pieces(text: str):
    pieces = []
    depth = 0
    group_start = None
    literal_start = 0
    for i, c in enumerate(text):
        if c == "{":
            if depth == 0:
                if literal_start < i:
                    pieces.append(("literal", text[literal_start:i]))
                group_start = i
            depth += 1
        elif c == "}":
            if depth == 0:
                raise BraceExpandError(f"unmatched '}}' at position {i}")
            depth -= 1
            if depth == 0:
                content = text[group_start + 1 : i]
                alts = [_parse_pieces(a) for a in _split_top_level(content)]
                pieces.append(("choice", alts))
                literal_start = i + 1
                group_start = None
    if depth != 0:
        raise BraceExpandError(f"unmatched '{{' in {text!r}")
    if literal_start < len(text):
        pieces.append(("literal", text[literal_start:]))
    return pieces


def _expand_pieces(pieces) -> List[str]:
    results = [""]
    for kind, value in pieces:
        next_results = []
        if kind == "literal":
            for prefix in results:
                next_results.append(prefix + value)
        else:
            for prefix in results:
                for alt in value:
                    for expanded in _expand_pieces(alt):
                        next_results.append(prefix + expanded)
        results = next_results
    return results


def expand(token: str) -> List[str]:
    return _expand_pieces(_parse_pieces(token))


def expand_or_literal(token: str) -> List[str]:
    try:
        return expand(token)
    except BraceExpandError:
        return [token]


def cartesian(fields: List[List[str]]) -> List[List[str]]:
    return [list(combo) for combo in product(*fields)] if fields else [[]]

"""Customer data access API.

All reads go through :class:`Client`, which returns :class:`Row` objects
whose fields are canonicalized at read time:

- email: strip + Unicode NFC + zero-width chars removed (U+200B, U+FEFF)
  + casefold
- display name: strip + Unicode NFC + internal whitespace collapsed
  + title-case

The module-level :func:`query` survives as a raw compatibility shim for
legacy callers and returns the stored dict untouched (uncanonicalized).
"""

import unicodedata

_ZERO_WIDTH_CHARS = ("\u200b", "\ufeff")

_ROWS = {
    "user": {
        1: {
            "email": " A\u200blice@Example.COM ",
            "display_name": "  alice   JOHNSON ",
        },
        2: {
            "email": "BOB@example.com",
            "display_name": "bob\u200b   smith",
        },
        3: {
            "email": "\ufeffCarol@Example.com",
            "display_name": "CAROL  williams",
        },
    }
}


def _strip_zero_width(value):
    for ch in _ZERO_WIDTH_CHARS:
        value = value.replace(ch, "")
    return value


def _canon_email(value):
    value = unicodedata.normalize("NFC", value.strip())
    value = _strip_zero_width(value)
    return value.casefold()


def _canon_display_name(value):
    value = unicodedata.normalize("NFC", value.strip())
    value = _strip_zero_width(value)
    value = " ".join(value.split())
    return value.title()


_FIELD_CANON = {
    "email": _canon_email,
    "display_name": _canon_display_name,
}


class Row:
    """One canonicalized record. Fields are plain attributes."""

    def __init__(self, entity, id, raw):
        self.entity = entity
        self.id = id
        for key, value in raw.items():
            canon = _FIELD_CANON.get(key)
            setattr(self, key, canon(value) if canon is not None else value)

    def as_dict(self):
        return {
            key: value
            for key, value in vars(self).items()
            if key not in ("entity", "id")
        }

    def __repr__(self):
        return f"Row(entity={self.entity!r}, id={self.id!r}, {self.as_dict()!r})"


class Client:
    """Canonical read access to the data store."""

    def __init__(self, rows=None):
        self._rows = _ROWS if rows is None else rows

    def query(self, entity, id):
        """Return the canonicalized Row for (entity, id), or None."""
        raw = self._rows.get(entity, {}).get(id)
        if raw is None:
            return None
        return Row(entity, id, raw)


def query(entity, id):
    """Legacy raw shim: uncanonicalized dict for (entity, id), or None."""
    raw = _ROWS.get(entity, {}).get(id)
    return dict(raw) if raw is not None else None

import unittest

import service


class ServiceTests(unittest.TestCase):
