"""Customer data access API (v1).

The store keeps data canonical (emails lowercase/trimmed, display names
title-cased), so reads are plain dict lookups: no post-processing needed.
"""

_ROWS = {
    "user": {
        1: {"email": "alice@example.com", "display_name": "Alice Johnson"},
        2: {"email": "bob@example.com", "display_name": "Bob Smith"},
    }
}


def query(entity, id):
    """Return the record for (entity, id) as a plain dict, or None."""
    raw = _ROWS.get(entity, {}).get(id)
    return dict(raw) if raw is not None else None

import unittest

import fmt
import report

# "café" decomposed: e + combining acute accent (display width 4, len() 5).
CAFE_DECOMPOSED = "cafe\u0301"
# "café" composed: single code point U+00E9.
CAFE_COMPOSED = "caf\u00e9"


class BannerTests(unittest.TestCase):
    def test_plain_ascii(self):
        self.assertEqual(report.banner(["ab", "cd"]), "ab--------|cd--------")

    def test_single_item(self):
        self.assertEqual(report.banner(["hello"]), "hello-----")

    def test_empty_items(self):
        self.assertEqual(report.banner([]), "")

    def test_decomposed_unicode_padded_by_display_width(self):
        expected = CAFE_DECOMPOSED + "-" * 6 + "|" + "x" + "-" * 9
        self.assertEqual(report.banner([CAFE_DECOMPOSED, "x"]), expected)

    def test_composed_and_decomposed_same_display_width(self):
        self.assertEqual(fmt.display_width(report.banner([CAFE_COMPOSED])), 10)
        self.assertEqual(fmt.display_width(report.banner([CAFE_DECOMPOSED])), 10)


if __name__ == "__main__":
    unittest.main()

"""Legacy text helpers.

The original v1 formatting utility. Superseded by fmt.py, kept only so
old imports don't break. pad() measures plain len(), which miscounts
strings containing decomposed unicode.
"""


def pad(s, width, fill=" "):
    """Pad s on the right with fill until len(s) == width."""
    if len(s) >= width:
        return s
    return s + fill * (width - len(s))

