//! Application version detection.
//!
//! Order: CLI override → `config.json` → `Cargo.toml` → `package.json`
//! → latest git tag.

use crate::error::{Result, SkillasticError};
use crate::git::Git;
use crate::model::Config;
use semver::Version;
use std::fs;
use std::path::Path;

pub fn detect(project_root: &Path, config: &Config, cli_override: Option<&str>) -> Result<Version> {
    if let Some(raw) = cli_override {
        return parse(raw);
    }
    if let Some(v) = &config.app_version {
        return Ok(v.clone());
    }
    if let Some(v) = from_cargo_toml(project_root) {
        return Ok(v);
    }
    if let Some(v) = from_package_json(project_root) {
        return Ok(v);
    }
    if let Ok(git) = Git::open(project_root) {
        if let Some(tag) = git.latest_tag("HEAD", false) {
            if let Ok(v) = parse(&tag) {
                return Ok(v);
            }
        }
    }
    Err(SkillasticError::Other(
        "could not detect the application version; pass --app-version or set app_version in .skillastic/config.json".into(),
    ))
}

/// Parse a semver string, tolerating a leading `v`.
pub fn parse(raw: &str) -> Result<Version> {
    Ok(Version::parse(raw.trim().trim_start_matches('v'))?)
}

fn from_cargo_toml(root: &Path) -> Option<Version> {
    let contents = fs::read_to_string(root.join("Cargo.toml")).ok()?;
    let mut in_package = false;
    for line in contents.lines() {
        let line = line.trim();
        if line.starts_with('[') {
            in_package = line == "[package]";
            continue;
        }
        if in_package {
            if let Some((key, value)) = line.split_once('=') {
                if key.trim() == "version" {
                    return Version::parse(value.trim().trim_matches('"')).ok();
                }
            }
        }
    }
    None
}

fn from_package_json(root: &Path) -> Option<Version> {
    let raw = fs::read_to_string(root.join("package.json")).ok()?;
    let json: serde_json::Value = serde_json::from_str(&raw).ok()?;
    Version::parse(json.get("version")?.as_str()?).ok()
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn detection_order() {
        let dir = TempDir::new().unwrap();
        let config = Config::default();

        // Nothing yet.
        assert!(detect(dir.path(), &config, None).is_err());
        // CLI override wins even over manifests.
        fs::write(
            dir.path().join("Cargo.toml"),
            "[package]\nversion = \"1.2.3\"\n",
        )
        .unwrap();
        assert_eq!(
            detect(dir.path(), &config, Some("9.9.9")).unwrap(),
            Version::new(9, 9, 9)
        );
        // Manifest detection.
        assert_eq!(
            detect(dir.path(), &config, None).unwrap(),
            Version::new(1, 2, 3)
        );
        // Config pin beats the manifest.
        let pinned = Config {
            app_version: Some(Version::new(2, 0, 0)),
            ..Default::default()
        };
        assert_eq!(
            detect(dir.path(), &pinned, None).unwrap(),
            Version::new(2, 0, 0)
        );
    }

    #[test]
    fn tolerates_leading_v() {
        assert_eq!(parse("v3.0.0").unwrap(), Version::new(3, 0, 0));
    }
}

//! Commit Archaeology Engine: reconstructs how the application evolved
//! between two refs — commits, breaking markers, file churn, dependency
//! movement, toolchain changes.

use crate::error::{Result, SkillasticError};
use crate::git::{Commit, FileChange, Git};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::path::Path;

/// Dependency movement between two refs.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct DepChanges {
    pub added: BTreeMap<String, String>,
    pub removed: BTreeMap<String, String>,
    /// name → (old req, new req)
    pub changed: BTreeMap<String, (String, String)>,
}

impl DepChanges {
    pub fn any(&self) -> bool {
        !self.added.is_empty() || !self.removed.is_empty() || !self.changed.is_empty()
    }

    pub fn is_empty(&self) -> bool {
        !self.any()
    }
}

/// Toolchain marker files that appeared/disappeared between refs.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ToolchainChanges {
    pub appeared: Vec<String>,
    pub disappeared: Vec<String>,
}

/// The full evolution record between two refs.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CommitChain {
    pub from_ref: String,
    pub to_ref: String,
    pub commits: Vec<Commit>,
    /// Commits carrying a breaking-change marker.
    pub breaking: Vec<Commit>,
    pub file_changes: Vec<FileChange>,
    pub dep_changes: DepChanges,
    pub toolchain_changes: ToolchainChanges,
}

/// Manifests we know how to diff for dependency movement.
const MANIFESTS: &[&str] = &["package.json", "Cargo.toml", "requirements.txt"];

/// Toolchain marker file → human name. Probed at each ref.
pub(crate) const TOOLCHAIN_FILES: &[(&str, &str)] = &[
    ("webpack.config.js", "webpack"),
    ("webpack.config.ts", "webpack"),
    ("vite.config.js", "vite"),
    ("vite.config.ts", "vite"),
    ("vite.config.mjs", "vite"),
    ("next.config.js", "next.js"),
    ("next.config.mjs", "next.js"),
    ("next.config.ts", "next.js"),
    ("tsconfig.json", "typescript"),
    ("Dockerfile", "docker"),
    ("docker-compose.yml", "docker-compose"),
    ("compose.yml", "docker-compose"),
    ("tailwind.config.js", "tailwind"),
    ("tailwind.config.ts", "tailwind"),
    ("babel.config.js", "babel"),
    (".babelrc", "babel"),
    ("jest.config.js", "jest"),
    ("jest.config.ts", "jest"),
    ("vitest.config.ts", "vitest"),
    ("eslint.config.js", "eslint"),
    (".eslintrc.json", "eslint"),
    ("rust-toolchain.toml", "rust-toolchain"),
];

pub struct Archaeology {
    git: Git,
}

impl Archaeology {
    pub fn new(project_root: &Path) -> Result<Self> {
        Ok(Self {
            git: Git::open(project_root)?,
        })
    }

    pub fn git(&self) -> &Git {
        &self.git
    }

    /// Analyze the chain between two version/ref names.
    pub fn analyze(&self, from: &str, to: &str) -> Result<CommitChain> {
        let from_ref = self
            .git
            .resolve_ref(from)
            .ok_or_else(|| SkillasticError::Git(format!("cannot resolve ref '{from}'")))?;
        let to_ref = self
            .git
            .resolve_ref(to)
            .ok_or_else(|| SkillasticError::Git(format!("cannot resolve ref '{to}'")))?;
        self.analyze_refs(&from_ref, &to_ref)
    }

    /// Analyze the chain between two already-resolved refs.
    pub fn analyze_refs(&self, from_ref: &str, to_ref: &str) -> Result<CommitChain> {
        let commits = self.git.log(from_ref, to_ref)?;
        let breaking = commits.iter().filter(|c| is_breaking(c)).cloned().collect();
        let file_changes = self.git.diff_name_status(from_ref, to_ref)?;
        let dep_changes = self.dep_changes(from_ref, to_ref);
        let toolchain_changes = self.toolchain_changes(from_ref, to_ref);
        Ok(CommitChain {
            from_ref: from_ref.to_string(),
            to_ref: to_ref.to_string(),
            commits,
            breaking,
            file_changes,
            dep_changes,
            toolchain_changes,
        })
    }

    /// Did dependencies move between two refs? Used by the resolver for
    /// the "unknown dependency change" rule.
    pub fn deps_changed(&self, from_ref: &str, to_ref: &str) -> bool {
        self.dep_changes(from_ref, to_ref).any()
    }

    /// Default starting point for an analysis: the tag before `to`.
    pub fn previous_tag(&self, to: &str) -> Option<String> {
        self.git.latest_tag(to, true)
    }

    fn dep_changes(&self, from_ref: &str, to_ref: &str) -> DepChanges {
        let mut old = BTreeMap::new();
        let mut new = BTreeMap::new();
        for manifest in MANIFESTS {
            if let Some(raw) = self.git.show_file(from_ref, manifest) {
                old.extend(parse_manifest(manifest, &raw));
            }
            if let Some(raw) = self.git.show_file(to_ref, manifest) {
                new.extend(parse_manifest(manifest, &raw));
            }
        }
        diff_deps(&old, &new)
    }

    fn toolchain_changes(&self, from_ref: &str, to_ref: &str) -> ToolchainChanges {
        let at = |ref_: &str| -> Vec<&str> {
            TOOLCHAIN_FILES
                .iter()
                .filter(|(file, _)| self.git.file_exists(ref_, file))
                .map(|(_, name)| *name)
                .collect()
        };
        let before = at(from_ref);
        let after = at(to_ref);
        ToolchainChanges {
            appeared: after
                .iter()
                .filter(|t| !before.contains(t))
                .map(|s| s.to_string())
                .collect(),
            disappeared: before
                .iter()
                .filter(|t| !after.contains(t))
                .map(|s| s.to_string())
                .collect(),
        }
    }
}

/// Conventional-commit and trailer based breaking-change detection.
pub fn is_breaking(commit: &Commit) -> bool {
    let subject_breaks = {
        // `type(scope)!:` or `type!:` — '!' immediately before the colon.
        let head = commit.subject.split(':').next().unwrap_or_default();
        head.ends_with('!') && commit.subject.contains(':')
    };
    subject_breaks
        || commit.body.contains("BREAKING CHANGE")
        || commit.body.contains("BREAKING-CHANGE")
}

/// Parse a manifest into (name → version req) pairs.
pub fn parse_manifest(filename: &str, contents: &str) -> BTreeMap<String, String> {
    match filename {
        "package.json" => parse_package_json(contents),
        "Cargo.toml" => parse_cargo_toml(contents),
        "requirements.txt" => parse_requirements(contents),
        _ => BTreeMap::new(),
    }
}

fn parse_package_json(contents: &str) -> BTreeMap<String, String> {
    let Ok(json) = serde_json::from_str::<serde_json::Value>(contents) else {
        return BTreeMap::new();
    };
    let mut deps = BTreeMap::new();
    for section in ["dependencies", "devDependencies"] {
        if let Some(map) = json.get(section).and_then(|s| s.as_object()) {
            for (name, ver) in map {
                deps.insert(name.clone(), ver.as_str().unwrap_or_default().to_string());
            }
        }
    }
    deps
}

/// Minimal line parser covering the common `[dependencies]` shapes:
/// `name = "ver"` and `name = { version = "ver", ... }`.
fn parse_cargo_toml(contents: &str) -> BTreeMap<String, String> {
    let mut deps = BTreeMap::new();
    let mut in_deps = false;
    for line in contents.lines() {
        let line = line.trim();
        if line.starts_with('[') {
            in_deps = line.trim_matches(['[', ']']).ends_with("dependencies");
            continue;
        }
        if !in_deps || line.starts_with('#') {
            continue;
        }
        let Some((name, value)) = line.split_once('=') else {
            continue;
        };
        let name = name.trim().trim_matches('"');
        if name.is_empty() {
            continue;
        }
        let value = value.trim();
        let version =
            if let Some(quoted) = value.strip_prefix('"').and_then(|v| v.strip_suffix('"')) {
                quoted.to_string()
            } else if value.starts_with('{') {
                // Inline table: find `version = "..."`.
                value
                    .trim_start_matches('{')
                    .trim_end_matches('}')
                    .split(',')
                    .filter_map(|kv| kv.split_once('='))
                    .find(|(k, _)| k.trim() == "version")
                    .map(|(_, v)| v.trim().trim_matches(|c| c == '"' || c == '}').to_string())
                    .unwrap_or_default()
            } else {
                continue;
            };
        deps.insert(name.to_string(), version);
    }
    deps
}

fn parse_requirements(contents: &str) -> BTreeMap<String, String> {
    let mut deps = BTreeMap::new();
    for line in contents.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') || line.starts_with('-') {
            continue;
        }
        if let Some((name, ver)) = line.split_once("==") {
            deps.insert(name.trim().to_string(), ver.trim().to_string());
        } else {
            deps.insert(line.to_string(), String::new());
        }
    }
    deps
}

fn diff_deps(old: &BTreeMap<String, String>, new: &BTreeMap<String, String>) -> DepChanges {
    let mut changes = DepChanges::default();
    for (name, ver) in new {
        match old.get(name) {
            None => {
                changes.added.insert(name.clone(), ver.clone());
            }
            Some(old_ver) if old_ver != ver => {
                changes
                    .changed
                    .insert(name.clone(), (old_ver.clone(), ver.clone()));
            }
            _ => {}
        }
    }
    for (name, ver) in old {
        if !new.contains_key(name) {
            changes.removed.insert(name.clone(), ver.clone());
        }
    }
    changes
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn breaking_markers() {
        let breaking_subject = Commit {
            hash: "a".into(),
            subject: "feat(api)!: drop v1 endpoints".into(),
            body: String::new(),
        };
        let breaking_body = Commit {
            hash: "b".into(),
            subject: "feat: rework config".into(),
            body: "Some text\n\nBREAKING CHANGE: config file moved".into(),
        };
        let normal = Commit {
            hash: "c".into(),
            subject: "fix: typo!".into(),
            body: String::new(),
        };
        assert!(is_breaking(&breaking_subject));
        assert!(is_breaking(&breaking_body));
        assert!(!is_breaking(&normal));
    }

    #[test]
    fn package_json_parsing() {
        let raw = r#"{
            "dependencies": { "react": "^18.2.0", "next": "14.0.0" },
            "devDependencies": { "vitest": "^1.0.0" }
        }"#;
        let deps = parse_manifest("package.json", raw);
        assert_eq!(deps.get("react").unwrap(), "^18.2.0");
        assert_eq!(deps.get("next").unwrap(), "14.0.0");
        assert_eq!(deps.get("vitest").unwrap(), "^1.0.0");
    }

    #[test]
    fn cargo_toml_parsing() {
        let raw = r#"
[package]
name = "x"

[dependencies]
serde = { version = "1", features = ["derive"] }
semver = "1"
# comment = "ignored"

[dev-dependencies]
tempfile = "3"
"#;
        let deps = parse_manifest("Cargo.toml", raw);
        assert_eq!(deps.get("serde").unwrap(), "1");
        assert_eq!(deps.get("semver").unwrap(), "1");
        assert_eq!(deps.get("tempfile").unwrap(), "3");
        assert!(!deps.contains_key("name")); // [package] section ignored
    }

    #[test]
    fn dep_diff() {
        let old: BTreeMap<_, _> = [("redux", "5.0"), ("react", "18.0")]
            .iter()
            .map(|(a, b)| (a.to_string(), b.to_string()))
            .collect();
        let new: BTreeMap<_, _> = [("react", "19.0"), ("zustand", "4.5")]
            .iter()
            .map(|(a, b)| (a.to_string(), b.to_string()))
            .collect();
        let diff = diff_deps(&old, &new);
        assert!(diff.added.contains_key("zustand"));
        assert!(diff.removed.contains_key("redux"));
        assert_eq!(
            diff.changed.get("react").unwrap(),
            &("18.0".into(), "19.0".into())
        );
        assert!(diff.any());
    }
}

//! Deterministic project-wide audit of Skillastic workspaces.
//!
//! Discovery and workspace health are intentionally local and deterministic.
//! Optional `bound`/Groq enrichment is advisory and never changes the local
//! recommendation.

use crate::error::Result;
use serde::{Deserialize, Serialize};
use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

const IGNORED_DIRS: &[&str] = &[
    ".git",
    ".skillastic",
    "target",
    "node_modules",
    "dist",
    "build",
    ".next",
    "coverage",
    "__pycache__",
    ".venv",
    "vendor",
];
const MARKERS: &[&str] = &[
    "Cargo.toml",
    "package.json",
    "pyproject.toml",
    "go.mod",
    "README.md",
];

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuditReport {
    pub root: String,
    pub sources: Vec<String>,
    pub projects: Vec<ProjectAudit>,
    pub totals: AuditTotals,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub inference: Option<InferenceReport>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProjectAudit {
    pub path: String,
    pub name: String,
    pub markers: Vec<String>,
    pub workspace: WorkspaceAudit,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WorkspaceAudit {
    pub state: WorkspaceState,
    pub skill_count: usize,
    pub valid_skill_count: usize,
    pub invalid_skill_files: Vec<String>,
    pub missing_bodies: Vec<String>,
    pub reasons: Vec<String>,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum WorkspaceState {
    Missing,
    Incomplete,
    Empty,
    Ready,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct AuditTotals {
    pub projects: usize,
    pub missing: usize,
    pub incomplete: usize,
    pub empty: usize,
    pub ready: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InferenceReport {
    pub provider: String,
    pub model: String,
    pub status: String,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub recommendations: Vec<InferenceRecommendation>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InferenceRecommendation {
    pub path: String,
    pub priority: String,
    pub rationale: String,
}

pub fn run(
    root: &Path,
    extra_sources: &[PathBuf],
    infer: bool,
    model: &str,
) -> Result<AuditReport> {
    let mut sources = vec![root.to_path_buf()];
    sources.extend(extra_sources.iter().cloned());
    for name in ["projects", "vico-projects", "work", "src"] {
        let path = root.join(name);
        if path.is_dir() {
            sources.push(path);
        }
    }
    sources.sort();
    sources.dedup();
    let mut project_paths = BTreeSet::new();
    for source in &sources {
        for project in discover_projects(source)? {
            project_paths.insert(project);
        }
    }
    let projects = project_paths
        .into_iter()
        .map(|path| inspect_project(root, &path))
        .collect::<Result<Vec<_>>>()?;
    let totals = projects.iter().fold(AuditTotals::default(), |mut t, p| {
        t.projects += 1;
        match p.workspace.state {
            WorkspaceState::Missing => t.missing += 1,
            WorkspaceState::Incomplete => t.incomplete += 1,
            WorkspaceState::Empty => t.empty += 1,
            WorkspaceState::Ready => t.ready += 1,
        }
        t
    });
    let inference = infer.then(|| infer_recommendations(root, &projects, model));
    Ok(AuditReport {
        root: root.display().to_string(),
        sources: sources.iter().map(|s| s.display().to_string()).collect(),
        projects,
        totals,
        inference,
    })
}

fn discover_projects(root: &Path) -> Result<Vec<PathBuf>> {
    let mut found = BTreeSet::new();
    walk(root, 0, false, true, &mut found)?;
    Ok(found.into_iter().collect())
}

fn walk(
    dir: &Path,
    depth: usize,
    inside_project: bool,
    is_scan_root: bool,
    found: &mut BTreeSet<PathBuf>,
) -> Result<()> {
    if depth > 3 {
        return Ok(());
    }
    let mut markers = Vec::new();
    for marker in MARKERS {
        if dir.join(marker).is_file() {
            markers.push(*marker);
        }
    }
    let git_root = dir.join(".git").is_dir();
    let has_manifest = markers.iter().any(|m| *m != "README.md");
    let has_nested_git = fs::read_dir(dir)
        .ok()
        .into_iter()
        .flatten()
        .filter_map(|entry| entry.ok())
        .any(|entry| entry.path().join(".git").is_dir());
    if (git_root && !is_scan_root && !(markers.is_empty() && has_nested_git))
        || (!is_scan_root && !inside_project && has_manifest)
    {
        found.insert(dir.to_path_buf());
    }
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        if !entry.file_type()?.is_dir() {
            continue;
        }
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.starts_with('.') || IGNORED_DIRS.contains(&name.as_str()) {
            continue;
        }
        walk(
            &entry.path(),
            depth + 1,
            inside_project || git_root,
            false,
            found,
        )?;
    }
    Ok(())
}

fn inspect_project(root: &Path, path: &Path) -> Result<ProjectAudit> {
    let mut markers = MARKERS
        .iter()
        .filter(|m| path.join(m).is_file())
        .map(|m| (*m).into())
        .collect::<Vec<String>>();
    if path.join(".git").is_dir() {
        markers.push(".git".into());
    }
    markers.sort();
    let relative = path.strip_prefix(root).unwrap_or(path);
    let name = path
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| "root".into());
    Ok(ProjectAudit {
        path: relative.display().to_string(),
        name,
        markers,
        workspace: inspect_workspace(path)?,
    })
}

fn inspect_workspace(project: &Path) -> Result<WorkspaceAudit> {
    let dir = project.join(".skillastic");
    if !dir.is_dir() {
        return Ok(WorkspaceAudit {
            state: WorkspaceState::Missing,
            skill_count: 0,
            valid_skill_count: 0,
            invalid_skill_files: Vec::new(),
            missing_bodies: Vec::new(),
            reasons: vec!["no .skillastic directory".into()],
        });
    }
    let mut reasons = Vec::new();
    for required in ["config.json", "state.json"] {
        if !dir.join(required).is_file() {
            reasons.push(format!("missing .skillastic/{required}"));
        }
    }
    let skills_dir = dir.join("skills");
    let mut skill_count = 0;
    let mut valid_skill_count = 0;
    let mut invalid = Vec::new();
    let mut missing_bodies = Vec::new();
    if skills_dir.is_dir() {
        for entry in fs::read_dir(&skills_dir)? {
            let path = entry?.path();
            if path.extension().and_then(|e| e.to_str()) != Some("json") {
                continue;
            }
            skill_count += 1;
            let file = path.file_name().unwrap().to_string_lossy().into_owned();
            let raw = fs::read_to_string(&path)?;
            let parsed = serde_json::from_str::<crate::model::Skill>(&raw);
            let valid = parsed.is_ok();
            if valid {
                valid_skill_count += 1;
            } else {
                invalid.push(file.clone());
            }
            let body = parsed
                .ok()
                .map(|skill| skills_dir.join(skill.body_path))
                .unwrap_or_else(|| path.with_extension("md"));
            if !body.is_file() {
                missing_bodies.push(file.trim_end_matches(".json").to_string());
            }
        }
    } else if skill_count > 0 {
        reasons.push("missing .skillastic/skills directory".into());
    }
    if !invalid.is_empty() {
        reasons.push("invalid skill metadata JSON".into());
    }
    if !missing_bodies.is_empty() {
        reasons.push("skill metadata has no matching Markdown body".into());
    }
    let state = if skill_count == 0 && reasons.is_empty() {
        WorkspaceState::Empty
    } else if reasons.is_empty() {
        WorkspaceState::Ready
    } else {
        WorkspaceState::Incomplete
    };
    Ok(WorkspaceAudit {
        state,
        skill_count,
        valid_skill_count,
        invalid_skill_files: invalid,
        missing_bodies,
        reasons,
    })
}

fn infer_recommendations(root: &Path, projects: &[ProjectAudit], model: &str) -> InferenceReport {
    let mut report = InferenceReport {
        provider: "groq".into(),
        model: model.into(),
        status: "not_run".into(),
        recommendations: Vec::new(),
        error: None,
    };
    let Some(key) = std::env::var_os("GROQ_API_KEY") else {
        report.status = "skipped_no_api_key".into();
        return report;
    };
    let mut bundle = String::new();
    for project in projects
        .iter()
        .filter(|p| p.workspace.state != WorkspaceState::Ready)
    {
        if bundle.len() > 120_000 {
            break;
        }
        bundle.push_str(&format!(
            "PROJECT {} STATE {:?} MARKERS {:?}\n",
            project.path, project.workspace.state, project.markers
        ));
        let path = root.join(&project.path);
        let output = Command::new("bound")
            .args([
                "--json",
                "--meta",
                "--tree",
                "--depth-limit",
                "1",
                "--token-limit",
                "600",
            ])
            .current_dir(&path)
            .output();
        if let Ok(output) = output {
            if output.status.success() {
                bundle.push_str(&String::from_utf8_lossy(&output.stdout));
            }
        }
        bundle.push('\n');
    }
    let prompt = format!(
        "Return a JSON object with a recommendations array. Each item must have path, priority (high|medium|low), rationale. Identify which projects should receive a .skillastic workspace next. Do not invent projects. Deterministic audit is authoritative; use this bundle only to prioritize.\n{bundle}"
    );
    let payload = serde_json::json!({"model": model, "temperature": 0, "response_format": {"type": "json_object"}, "messages": [{"role": "system", "content": "You audit software project metadata."}, {"role": "user", "content": prompt}]});
    let key = key.to_string_lossy();
    let output = Command::new("curl")
        .args([
            "-sS",
            "https://api.groq.com/openai/v1/chat/completions",
            "-H",
            &format!("Authorization: Bearer {key}"),
            "-H",
            "Content-Type: application/json",
            "--data",
            &payload.to_string(),
        ])
        .output();
    let Ok(output) = output else {
        report.status = "failed_curl".into();
        report.error = Some("could not start curl".into());
        return report;
    };
    if !output.status.success() {
        report.status = "failed_api".into();
        report.error = Some(String::from_utf8_lossy(&output.stderr).trim().to_string());
        return report;
    }
    let response: serde_json::Value = match serde_json::from_slice(&output.stdout) {
        Ok(v) => v,
        Err(e) => {
            report.status = "invalid_api_response".into();
            report.error = Some(e.to_string());
            return report;
        }
    };
    let text = response["choices"][0]["message"]["content"]
        .as_str()
        .unwrap_or_default()
        .trim();
    let clean = text
        .strip_prefix("```json")
        .unwrap_or(text)
        .strip_suffix("```")
        .unwrap_or(text)
        .trim();
    let parsed = serde_json::from_str::<serde_json::Value>(clean).and_then(|value| {
        let value = value.get("recommendations").cloned().unwrap_or(value);
        serde_json::from_value::<Vec<InferenceRecommendation>>(value)
    });
    match parsed {
        Ok(items) => {
            report.status = "complete".into();
            report.recommendations = items;
        }
        Err(e) => {
            report.status = "invalid_model_output".into();
            report.error = Some(e.to_string());
        }
    }
    report
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn audit_distinguishes_missing_empty_and_ready() {
        let dir = TempDir::new().unwrap();
        fs::write(dir.path().join("README.md"), "root").unwrap();
        fs::write(
            dir.path().join("Cargo.toml"),
            "[package]\nname=\"root\"\nversion=\"0.1.0\"\n",
        )
        .unwrap();
        let missing = dir.path().join("missing");
        fs::create_dir_all(&missing).unwrap();
        fs::write(
            missing.join("Cargo.toml"),
            "[package]\nname=\"missing\"\nversion=\"0.1.0\"\n",
        )
        .unwrap();
        let ready = dir.path().join("ready");
        fs::create_dir_all(ready.join(".skillastic/skills")).unwrap();
        fs::write(ready.join("README.md"), "ready").unwrap();
        fs::write(
            ready.join("Cargo.toml"),
            "[package]\nname=\"ready\"\nversion=\"0.1.0\"\n",
        )
        .unwrap();
        fs::write(ready.join("config.json"), "{}").unwrap_or(());
        fs::write(ready.join(".skillastic/config.json"), "{}").unwrap();
        fs::write(ready.join(".skillastic/state.json"), "{}").unwrap();
        let report = run(dir.path(), &[], false, "test").unwrap();
        assert!(
            report
                .projects
                .iter()
                .any(|p| p.workspace.state == WorkspaceState::Missing)
        );
        assert!(
            report
                .projects
                .iter()
                .any(|p| p.workspace.state == WorkspaceState::Empty)
        );
    }
}

//! Context Capture Engine: fingerprints what a codebase actually is —
//! frameworks, toolchains, directory shape, dependencies — either from the
//! working tree or reconstructed at a git ref.

use crate::archaeology::{TOOLCHAIN_FILES, parse_manifest};
use crate::error::Result;
use crate::git::Git;
use crate::model::ContextFingerprint;
use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

/// Manifests scanned for dependencies (mirrors archaeology).
const MANIFESTS: &[&str] = &["package.json", "Cargo.toml", "requirements.txt"];

/// Directories that carry no architectural signal.
const NOISE_DIRS: &[&str] = &[
    "target",
    "node_modules",
    ".git",
    ".skillastic",
    "dist",
    "build",
    "out",
    ".next",
    "coverage",
    "__pycache__",
    ".venv",
];

/// Dependency name → framework. Architecturally meaningful only —
/// low-level utilities (serde, lodash) are deliberately excluded.
const FRAMEWORK_DEPS: &[(&str, &str)] = &[
    ("next", "next.js"),
    ("react", "react"),
    ("@reduxjs/toolkit", "redux"),
    ("redux", "redux"),
    ("zustand", "zustand"),
    ("vue", "vue"),
    ("nuxt", "nuxt"),
    ("svelte", "svelte"),
    ("@angular/core", "angular"),
    ("express", "express"),
    ("fastify", "fastify"),
    ("tailwindcss", "tailwindcss"),
    ("tokio", "tokio"),
    ("axum", "axum"),
    ("actix-web", "actix-web"),
    ("sqlx", "sqlx"),
    ("diesel", "diesel"),
    ("ratatui", "ratatui"),
    ("django", "django"),
    ("flask", "flask"),
    ("fastapi", "fastapi"),
    ("sqlalchemy", "sqlalchemy"),
];

pub struct Capture;

impl Capture {
    /// Fingerprint the current working tree.
    pub fn scan(project_root: &Path) -> Result<ContextFingerprint> {
        let mut directories = Vec::new();
        for entry in fs::read_dir(project_root)? {
            let entry = entry?;
            if !entry.file_type()?.is_dir() {
                continue;
            }
            let name = entry.file_name().to_string_lossy().into_owned();
            if !name.starts_with('.') && !NOISE_DIRS.contains(&name.as_str()) {
                directories.push(name);
            }
        }

        let mut dependencies = BTreeMap::new();
        for manifest in MANIFESTS {
            let path = project_root.join(manifest);
            if path.is_file() {
                dependencies.extend(parse_manifest(manifest, &fs::read_to_string(path)?));
            }
        }

        let toolchains: Vec<String> = TOOLCHAIN_FILES
            .iter()
            .filter(|(file, _)| project_root.join(file).is_file())
            .map(|(_, name)| name.to_string())
            .collect();

        Ok(assemble(directories, dependencies, toolchains))
    }

    /// Reconstruct the fingerprint at a git ref (for old-context diffs).
    pub fn scan_ref(git: &Git, ref_: &str) -> Result<ContextFingerprint> {
        let directories: Vec<String> = git
            .ls_tree(ref_)?
            .into_iter()
            .filter_map(|name| {
                // ls_tree marks dirs with a trailing '/' when using --name-only
                // only with -d; probe entries ending in '/' or known by type.
                let name = name.trim_end_matches('/').to_string();
                if git_dir(git, ref_, &name)
                    && !name.starts_with('.')
                    && !NOISE_DIRS.contains(&name.as_str())
                {
                    Some(name)
                } else {
                    None
                }
            })
            .collect();

        let mut dependencies = BTreeMap::new();
        for manifest in MANIFESTS {
            if let Some(raw) = git.show_file(ref_, manifest) {
                dependencies.extend(parse_manifest(manifest, &raw));
            }
        }

        let toolchains: Vec<String> = TOOLCHAIN_FILES
            .iter()
            .filter(|(file, _)| git.file_exists(ref_, file))
            .map(|(_, name)| name.to_string())
            .collect();

        Ok(assemble(directories, dependencies, toolchains))
    }
}

/// Is `name` a directory at `ref_`? (ls-tree --name-only doesn't mark types.)
fn git_dir(git: &Git, ref_: &str, name: &str) -> bool {
    git.object_type(ref_, name).as_deref() == Some("tree")
}

fn assemble(
    mut directories: Vec<String>,
    dependencies: BTreeMap<String, String>,
    toolchains: Vec<String>,
) -> ContextFingerprint {
    directories.sort();
    directories.dedup();

    let mut frameworks: Vec<String> = FRAMEWORK_DEPS
        .iter()
        .filter(|(dep, _)| dependencies.contains_key(*dep))
        .map(|(_, fw)| fw.to_string())
        .collect();

    // Router flavour detection for next.js.
    if dependencies.contains_key("next") {
        if directories.iter().any(|d| d == "app") {
            frameworks.push("next.js app-router".into());
        }
        if directories.iter().any(|d| d == "pages") {
            frameworks.push("next.js pages-router".into());
        }
    }

    frameworks.sort();
    frameworks.dedup();

    let mut toolchains = toolchains;
    toolchains.sort();
    toolchains.dedup();

    ContextFingerprint {
        frameworks,
        toolchains,
        directories,
        dependencies,
    }
}

