//! Skillastic daemon: polls the application for version/HEAD changes and
//! re-resolves all skills, auto-migrating when configured.

use crate::appver;
use crate::archaeology::Archaeology;
use crate::error::Result;
use crate::git::Git;
use crate::migrate::Migrator;
use crate::model::Decision;
use crate::registry::Registry;
use crate::resolver::Resolver;
use chrono::Utc;
use std::time::Duration;

pub struct Daemon<'a> {
    registry: &'a Registry,
    interval: Duration,
}

impl<'a> Daemon<'a> {
    pub fn new(registry: &'a Registry, interval_secs: u64) -> Self {
        Self {
            registry,
            interval: Duration::from_secs(interval_secs.max(1)),
        }
    }

    /// Poll forever. Default SIGINT handling terminates the process.
    pub fn run(&self) -> Result<()> {
        println!(
            "skillastic daemon: watching {} every {}s",
            self.registry.project_root().display(),
            self.interval.as_secs()
        );
        loop {
            for event in self.tick()? {
                println!("[{}] {event}", Utc::now().format("%Y-%m-%d %H:%M:%S"));
            }
            std::thread::sleep(self.interval);
        }
    }

    /// One poll cycle. Returns the events that fired (empty when nothing
    /// changed). Kept separate from `run` for testability.
    pub fn tick(&self) -> Result<Vec<String>> {
        let mut events = Vec::new();
        let config = self.registry.config()?;
        let project_root = self.registry.project_root();
        let app_version = match appver::detect(&project_root, &config, None) {
            Ok(v) => v,
            Err(_) => return Ok(events), // undetectable version; try again next tick
        };
        let head = Git::open(&project_root).ok().and_then(|g| g.head().ok());
        let mut state = self.registry.state()?;

        let version_changed = state.last_app_version.as_ref() != Some(&app_version);
        let head_changed = head.is_some() && state.last_head.as_deref() != head.as_deref();

        if version_changed || head_changed {
            events.push(format!(
                "change detected: app {} -> {app_version}, head {:?} -> {:?}",
                state
                    .last_app_version
                    .as_ref()
                    .map(|v| v.to_string())
                    .unwrap_or_else(|| "?".into()),
                state.last_head,
                head
            ));

            let skills = self.registry.list_skills()?;
            if !skills.is_empty() {
                let arch = Archaeology::new(&project_root).ok();
                let resolver = Resolver::new(arch.as_ref(), &app_version);
                for res in resolver.resolve_all(&skills, &app_version)? {
                    events.push(format!(
                        "resolve {}: {} ({})",
                        res.skill, res.decision, res.reason
                    ));
                    self.registry.apply_resolution(&res)?;
                    if res.decision == Decision::Migrate && config.auto_migrate {
                        match Migrator::new(self.registry).migrate(&res.skill, &app_version, false)
                        {
                            Ok(outcome) => events.push(format!(
                                "migrated {}: skill {} -> {}",
                                outcome.skill, outcome.from_skill_version, outcome.to_skill_version
                            )),
                            Err(e) => {
                                events.push(format!("migration failed for {}: {e}", res.skill))
                            }
                        }
                    }
                }
            }

            state.last_app_version = Some(app_version);
            state.last_head = head;
        }

        state.last_check = Some(Utc::now());
        for event in &events {
            state.log(format!(
                "[{}] {event}",
                Utc::now().format("%Y-%m-%d %H:%M:%S")
            ));
        }
        self.registry.save_state(&state)?;
        Ok(events)
    }
}

/// Recent daemon events from `state.json`, for inspection.
pub fn recent_events(registry: &Registry) -> Result<Vec<String>> {
    Ok(registry.state()?.events)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{Config, Skill, SkillStatus};
    use semver::Version;
    use std::fs;
    use tempfile::TempDir;

    fn v(s: &str) -> Version {
        Version::parse(s).unwrap()
    }

    /// A temp project whose version comes from its Cargo.toml.
    fn setup(app_version: &str) -> (TempDir, Registry) {
        let dir = TempDir::new().unwrap();
        set_app_version(&dir, app_version);
        let registry = Registry::init(dir.path(), Config::default()).unwrap();
        (dir, registry)
    }

    fn set_app_version(dir: &TempDir, version: &str) {
        fs::write(
            dir.path().join("Cargo.toml"),
            format!("[package]\nname = \"t\"\nversion = \"{version}\"\n"),
        )
        .unwrap();
    }

    fn add_skill(registry: &Registry, range: &str, verified: &str) {
        let skill = Skill::new("web", v("1.0.0"), vec![range.into()], v(verified));
        registry.add_skill(&skill, "# Web\nUse the thing.").unwrap();
    }

    #[test]
    fn first_tick_establishes_baseline() {
        let (_dir, registry) = setup("1.0.0");
        add_skill(&registry, ">=1.0.0, <2.0.0", "1.0.0");
        let events = Daemon::new(&registry, 1).tick().unwrap();

        assert!(events.iter().any(|e| e.contains("change detected")));
        assert!(events.iter().any(|e| e.contains("resolve web: load")));
        let state = registry.state().unwrap();
        assert_eq!(state.last_app_version, Some(v("1.0.0")));
        assert!(state.last_check.is_some());
        assert_eq!(state.events.len(), events.len());
    }

    #[test]
    fn steady_state_tick_is_quiet() {
        let (_dir, registry) = setup("1.0.0");
        let daemon = Daemon::new(&registry, 1);
        assert!(!daemon.tick().unwrap().is_empty());
        assert!(daemon.tick().unwrap().is_empty());
    }

    #[test]
    fn version_bump_re_resolves_without_migrating() {
        let (dir, registry) = setup("1.0.0");
        add_skill(&registry, ">=1.0.0, <2.0.0", "1.0.0");
        let daemon = Daemon::new(&registry, 1);
        daemon.tick().unwrap();

        set_app_version(&dir, "1.1.0");
        let events = daemon.tick().unwrap();
        assert!(events.iter().any(|e| e.contains("resolve web: validate")));
        assert!(!events.iter().any(|e| e.contains("migrated")));
        // Minor bump: resolver only asks for validation; version untouched,
        // but the stored status reflects the decision.
        let skill = registry.load_skill("web").unwrap();
        assert_eq!(skill.verified_app_version, v("1.0.0"));
        assert_eq!(skill.status, SkillStatus::NeedsValidation);
    }

    #[test]
    fn auto_migrates_out_of_range_skills() {
        let (dir, registry) = setup("1.0.0");
        add_skill(&registry, ">=1.0.0, <2.0.0", "1.0.0");
        let daemon = Daemon::new(&registry, 1);
        daemon.tick().unwrap();

        set_app_version(&dir, "2.0.0");
        let events = daemon.tick().unwrap();
        assert!(events.iter().any(|e| e.contains("resolve web: migrate")));
        assert!(
            events
                .iter()
                .any(|e| e.starts_with("migrated web: skill 1.0.0 -> 2.0.0"))
        );

        let skill = registry.load_skill("web").unwrap();
        assert_eq!(skill.skill_version, v("2.0.0"));
        assert_eq!(skill.verified_app_version, v("2.0.0"));
        assert_eq!(registry.snapshots_for("web").unwrap(), vec!["web@1.0.0"]);
    }

    #[test]
    fn auto_migrate_disabled_leaves_skill_alone() {
        let (dir, registry) = setup("1.0.0");
        add_skill(&registry, ">=1.0.0, <2.0.0", "1.0.0");
        let mut config = registry.config().unwrap();
        config.auto_migrate = false;
        registry.save_config(&config).unwrap();
        let daemon = Daemon::new(&registry, 1);
        daemon.tick().unwrap();

        set_app_version(&dir, "2.0.0");
        let events = daemon.tick().unwrap();
        assert!(events.iter().any(|e| e.contains("resolve web: migrate")));
        assert!(!events.iter().any(|e| e.contains("migrated")));
        let skill = registry.load_skill("web").unwrap();
        assert_eq!(skill.verified_app_version, v("1.0.0"));
        assert_eq!(skill.status, SkillStatus::NeedsMigration);
    }

    #[test]
    fn recent_events_reads_state_log() {
        let (_dir, registry) = setup("1.0.0");
        let events = Daemon::new(&registry, 1).tick().unwrap();
        assert_eq!(recent_events(&registry).unwrap().len(), events.len());
    }
}

//! Context Delta: the deterministic difference between what a skill knows
//! and what the application has become, plus the append-only markdown patch
//! applied to skill bodies.

use crate::archaeology::CommitChain;
use crate::git::Commit;
use crate::model::ContextFingerprint;
use chrono::Utc;
use semver::Version;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ContextDelta {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub from_app: Option<Version>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub to_app: Option<Version>,
    #[serde(default)]
    pub removed_deps: BTreeMap<String, String>,
    #[serde(default)]
    pub added_deps: BTreeMap<String, String>,
    #[serde(default)]
    pub changed_deps: BTreeMap<String, (String, String)>,
    #[serde(default)]
    pub breaking_commits: Vec<Commit>,
    #[serde(default)]
    pub toolchain_appeared: Vec<String>,
    #[serde(default)]
    pub toolchain_disappeared: Vec<String>,
    #[serde(default)]
    pub frameworks_appeared: Vec<String>,
    #[serde(default)]
    pub frameworks_disappeared: Vec<String>,
    #[serde(default)]
    pub dirs_appeared: Vec<String>,
    #[serde(default)]
    pub dirs_disappeared: Vec<String>,
}

impl ContextDelta {
    /// Build the delta from commit archaeology + old/new fingerprints.
    pub fn build(
        chain: Option<&CommitChain>,
        from_app: Version,
        to_app: Version,
        old_fp: &ContextFingerprint,
        new_fp: &ContextFingerprint,
    ) -> Self {
        let mut delta = Self {
            from_app: Some(from_app),
            to_app: Some(to_app),
            ..Default::default()
        };

        if let Some(chain) = chain {
            delta.removed_deps = chain.dep_changes.removed.clone();
            delta.added_deps = chain.dep_changes.added.clone();
            delta.changed_deps = chain.dep_changes.changed.clone();
            delta.breaking_commits = chain.breaking.clone();
            delta.toolchain_appeared = chain.toolchain_changes.appeared.clone();
            delta.toolchain_disappeared = chain.toolchain_changes.disappeared.clone();
        }

        delta.frameworks_appeared = appeared(&old_fp.frameworks, &new_fp.frameworks);
        delta.frameworks_disappeared = appeared(&new_fp.frameworks, &old_fp.frameworks);
        delta.dirs_appeared = appeared(&old_fp.directories, &new_fp.directories);
        delta.dirs_disappeared = appeared(&new_fp.directories, &old_fp.directories);
        delta
    }

    pub fn is_empty(&self) -> bool {
        self.removed_deps.is_empty()
            && self.added_deps.is_empty()
            && self.changed_deps.is_empty()
            && self.breaking_commits.is_empty()
            && self.toolchain_appeared.is_empty()
            && self.toolchain_disappeared.is_empty()
            && self.frameworks_appeared.is_empty()
            && self.frameworks_disappeared.is_empty()
            && self.dirs_appeared.is_empty()
            && self.dirs_disappeared.is_empty()
    }

    /// One-line summary for `mutation_history`.
    pub fn reason(&self) -> String {
        let mut parts = Vec::new();
        if !self.added_deps.is_empty() {
            parts.push(format!("+{} deps", self.added_deps.len()));
        }
        if !self.removed_deps.is_empty() {
            parts.push(format!("-{} deps", self.removed_deps.len()));
        }
        if !self.changed_deps.is_empty() {
            parts.push(format!("~{} deps", self.changed_deps.len()));
        }
        if !self.breaking_commits.is_empty() {
            parts.push(format!("{} breaking", self.breaking_commits.len()));
        }
        if !self.frameworks_appeared.is_empty() {
            parts.push(format!("+{}", self.frameworks_appeared.join("+")));
        }
        if !self.frameworks_disappeared.is_empty() {
            parts.push(format!("-{}", self.frameworks_disappeared.join("-")));
        }
        if !self.toolchain_appeared.is_empty() {
            parts.push(format!("+{} toolchain", self.toolchain_appeared.join("+")));
        }
        if !self.toolchain_disappeared.is_empty() {
            parts.push(format!(
                "-{} toolchain",
                self.toolchain_disappeared.join("-")
            ));
        }
        let from = self
            .from_app
            .as_ref()
            .map(|v| v.to_string())
            .unwrap_or_else(|| "?".into());
        let to = self
            .to_app
            .as_ref()
            .map(|v| v.to_string())
            .unwrap_or_else(|| "?".into());
        if parts.is_empty() {
            format!("migrate app {from} -> {to}: no structural changes detected")
        } else {
            format!("migrate app {from} -> {to}: {}", parts.join(", "))
        }
    }

    /// Render the deterministic, append-only skill patch. The existing body
    /// is never rewritten — notes are reviewable diffs, not silent edits.
    pub fn to_markdown(&self) -> String {
        let to = self
            .to_app
            .as_ref()
            .map(|v| v.to_string())
            .unwrap_or_else(|| "?".into());
        let from = self
            .from_app
            .as_ref()
            .map(|v| v.to_string())
            .unwrap_or_else(|| "?".into());
        let mut out = format!(
            "\n\n---\n\n## Migration Notes (app v{to})\n\n\
             _Migrated from app v{from} on {}. Run `skillastic verify` after reviewing \
             these assumptions._\n",
            Utc::now().format("%Y-%m-%d")
        );

        if self.is_empty() {
            out.push_str("\nNo structural changes detected between these versions.\n");
            return out;
        }

        if !self.removed_deps.is_empty()
            || !self.frameworks_disappeared.is_empty()
            || !self.toolchain_disappeared.is_empty()
            || !self.dirs_disappeared.is_empty()
        {
            out.push_str("\n### Deprecated assumptions\n");
            for name in self.removed_deps.keys() {
                out.push_str(&format!(
                    "- Dependency `{name}` was removed — do not recommend it.\n"
                ));
            }
            for fw in &self.frameworks_disappeared {
                out.push_str(&format!(
                    "- Framework `{fw}` is no longer present — do not recommend it.\n"
                ));
            }
            for tc in &self.toolchain_disappeared {
                out.push_str(&format!(
                    "- Toolchain `{tc}` was removed — drop instructions that assume it.\n"
                ));
            }
            for d in &self.dirs_disappeared {
                out.push_str(&format!("- Directory `{d}/` no longer exists.\n"));
            }
        }

        if !self.added_deps.is_empty()
            || !self.frameworks_appeared.is_empty()
            || !self.toolchain_appeared.is_empty()
            || !self.dirs_appeared.is_empty()
        {
            out.push_str("\n### New capabilities\n");
            for (name, ver) in &self.added_deps {
                let ver = if ver.is_empty() {
                    String::new()
                } else {
                    format!(" ({ver})")
                };
                out.push_str(&format!("- Dependency `{name}`{ver} was added.\n"));
            }
            for fw in &self.frameworks_appeared {
                out.push_str(&format!(
                    "- Framework `{fw}` is now present — prefer it where applicable.\n"
                ));
            }
            for tc in &self.toolchain_appeared {
                out.push_str(&format!("- Toolchain `{tc}` is now in use.\n"));
            }
            for d in &self.dirs_appeared {
                out.push_str(&format!("- Directory `{d}/` now exists.\n"));
            }
        }

        if !self.changed_deps.is_empty() {
            out.push_str("\n### Updated dependencies\n");
            for (name, (old, new)) in &self.changed_deps {
                out.push_str(&format!("- `{name}`: {old} -> {new}\n"));
            }
        }

        if !self.breaking_commits.is_empty() {
            out.push_str("\n### Breaking changes\n");
            for c in &self.breaking_commits {
                out.push_str(&format!("- `{}` {}\n", c.hash, c.subject));
            }
        }

        out
    }
}

fn appeared(old: &[String], new: &[String]) -> Vec<String> {
    new.iter().filter(|x| !old.contains(x)).cloned().collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::archaeology::{DepChanges, ToolchainChanges};

    fn v(s: &str) -> Version {
        Version::parse(s).unwrap()
    }

    fn chain() -> CommitChain {
        CommitChain {
            from_ref: "v2.4.1".into(),
            to_ref: "v3.0.0".into(),
            commits: vec![],
            breaking: vec![Commit {
                hash: "a91f3e2".into(),
                subject: "feat(api)!: drop redux".into(),
                body: String::new(),
            }],
            file_changes: vec![],
            dep_changes: DepChanges {
                added: [("next".to_string(), "14.0.0".to_string())]
                    .into_iter()
                    .collect(),
                removed: [("redux".to_string(), "5.0.0".to_string())]
                    .into_iter()
                    .collect(),
                changed: [("react".to_string(), ("18.0.0".into(), "19.0.0".into()))]
                    .into_iter()
                    .collect(),
            },
            toolchain_changes: ToolchainChanges {
                appeared: vec!["vite".into()],
                disappeared: vec!["webpack".into()],
            },
        }
    }

    #[test]
    fn markdown_patch_sections() {
        let old_fp = ContextFingerprint {
            frameworks: vec!["react".into(), "redux".into()],
            directories: vec!["pages".into()],
            ..Default::default()
        };
        let new_fp = ContextFingerprint {
            frameworks: vec![
                "next.js".into(),
                "next.js app-router".into(),
                "react".into(),
            ],
            directories: vec!["app".into()],
            ..Default::default()
        };
        let delta = ContextDelta::build(Some(&chain()), v("2.4.1"), v("3.0.0"), &old_fp, &new_fp);
        assert!(!delta.is_empty());

        let md = delta.to_markdown();
        assert!(md.contains("## Migration Notes (app v3.0.0)"));
        assert!(md.contains("`redux` was removed"));
        assert!(md.contains("Framework `redux` is no longer present"));
        assert!(md.contains("Toolchain `webpack` was removed"));
        assert!(md.contains("`pages/` no longer exists"));
        assert!(md.contains("`next` (14.0.0) was added"));
        assert!(md.contains("`next.js app-router` is now present"));
        assert!(md.contains("`react`: 18.0.0 -> 19.0.0"));
        assert!(md.contains("`a91f3e2` feat(api)!: drop redux"));

        let reason = delta.reason();
        assert!(reason.contains("migrate app 2.4.1 -> 3.0.0"));
        assert!(reason.contains("1 breaking"));
    }

    #[test]
    fn empty_delta_renders_no_structural_changes() {
        let fp = ContextFingerprint::default();
        let delta = ContextDelta::build(None, v("1.0.0"), v("1.1.0"), &fp, &fp);
        assert!(delta.is_empty());
        assert!(
            delta
                .to_markdown()
                .contains("No structural changes detected")
        );
    }
}

//! Docs page generation for skills.

use crate::error::{Result, SkillasticError};
use crate::registry::Registry;
use crate::templates;
use std::fs;
use std::path::PathBuf;

pub fn generate(registry: &Registry, name: &str) -> Result<PathBuf> {
    let _skill = registry.load_skill(name)?;
    let docs_dir = registry.root().join("docs");
    fs::create_dir_all(&docs_dir)?;
    let path = docs_dir.join(format!("{name}.md"));

    let mut contents = format!(
        "# {}\n\n",
        name.split('-')
            .map(|w| {
                let mut c = w.chars();
                match c.next() {
                    None => String::new(),
                    Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
                }
            })
            .collect::<Vec<_>>()
            .join(" ")
    );
    contents.push_str(templates::DOCS_PAGE_TEMPLATE);

    fs::write(&path, contents)?;
    Ok(path)
}

pub fn render(registry: &Registry, name: &str) -> Result<String> {
    let path = registry.root().join("docs").join(format!("{name}.md"));
    if !path.is_file() {
        return Err(SkillasticError::Other(format!(
            "no docs page for '{name}'; run `skillastic docs generate {name}`"
        )));
    }
    Ok(fs::read_to_string(path)?)
}

//! Workspace health checks.

use crate::error::Result;
use crate::registry::Registry;
use std::collections::HashSet;

pub struct Diagnosis {
    pub healthy: bool,
    pub findings: Vec<String>,
}

pub fn diagnose(registry: &Registry) -> Result<Diagnosis> {
    let mut findings = Vec::new();

    // Workspace initialized check is implicit because we hold a Registry.

    let setup_files = [
        "agents/issue-tracker.md",
        "agents/triage-labels.md",
        "agents/domain.md",
    ];
    for file in &setup_files {
        if !registry.root().join(file).is_file() {
            findings.push(format!(
                "missing setup file: .skillastic/{file}; run `skillastic setup`"
            ));
        }
    }

    let skills = registry.list_skills()?;
    let names: HashSet<String> = skills.iter().map(|s| s.name.clone()).collect();

    for skill in &skills {
        let body_path = registry.root().join("skills").join(&skill.body_path);
        if !body_path.is_file() {
            findings.push(format!(
                "skill '{}' is missing its body at {}",
                skill.name,
                body_path.display()
            ));
        }
        for req in &skill.requires {
            if !names.contains(req) {
                findings.push(format!(
                    "skill '{}' requires missing skill '{}'",
                    skill.name, req
                ));
            }
        }
    }

    let promoted = registry.promoted()?;
    for name in &promoted.skills {
        if !names.contains(name) {
            findings.push(format!("promoted skill '{name}' is not registered"));
        }
    }

    let healthy = findings.is_empty();
    Ok(Diagnosis { healthy, findings })
}

//! Domain modeling support: CONTEXT.md and ADRs.

use crate::error::Result;
use crate::registry::Registry;
use crate::templates;
use std::fs;
use std::path::{Path, PathBuf};

/// Seed or update `CONTEXT.md` at the project root.
pub fn ensure_context_md(registry: &Registry) -> Result<PathBuf> {
    let path = registry.project_root().join("CONTEXT.md");
    if !path.exists() {
        fs::write(&path, templates::CONTEXT_MD_TEMPLATE)?;
    }
    Ok(path)
}

/// Create a new ADR in `.skillastic/adr/`.
pub fn create_adr(registry: &Registry, title: &str) -> Result<PathBuf> {
    let slug = slugify(title);
    let adr_dir = registry.root().join("adr");
    fs::create_dir_all(&adr_dir)?;

    let next_number = next_adr_number(&adr_dir)?;
    let filename = format!("{:04}-{}.md", next_number, slug);
    let path = adr_dir.join(&filename);

    let body = templates::ADR_TEMPLATE
        .replace("{number}", &format!("{:04}", next_number))
        .replace("{slug}", &slug)
        .replace("{title}", title);

    fs::write(&path, body)?;

    // Link from CONTEXT.md if it exists.
    let context_path = registry.project_root().join("CONTEXT.md");
    if context_path.is_file() {
        let mut context = fs::read_to_string(&context_path)?;
        if !context.contains("## Decisions") {
            context.push_str("\n\n## Decisions\n\n");
        }
        let link = format!(
            "- [{:04}. {}](.skillastic/adr/{})\n",
            next_number, title, filename
        );
        if !context.contains(&filename) {
            context.push_str(&link);
            fs::write(&context_path, context)?;
        }
    }

    Ok(path)
}

/// Extract candidate domain terms from a skillastic workspace's source files.
/// Very naive: looks for `pub fn`, `pub struct`, `pub enum`, `pub trait` declarations.
pub fn capture_domain_terms(project_root: &Path) -> Vec<String> {
    let src_dir = project_root.join("src");
    if !src_dir.is_dir() {
        return Vec::new();
    }

    let mut terms = Vec::new();
    if let Ok(entries) = fs::read_dir(&src_dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.extension().and_then(|e| e.to_str()) != Some("rs") {
                continue;
            }
            if let Ok(contents) = fs::read_to_string(&path) {
                for line in contents.lines() {
                    let line = line.trim();
                    if let Some(stripped) = line
                        .strip_prefix("pub fn ")
                        .or_else(|| line.strip_prefix("pub async fn "))
                    {
                        if let Some(name) = stripped.split(['(', '<']).next() {
                            terms.push(name.trim().to_string());
                        }
                    } else if let Some(stripped) = line
                        .strip_prefix("pub struct ")
                        .or_else(|| line.strip_prefix("pub enum "))
                        .or_else(|| line.strip_prefix("pub trait "))
                    {
                        if let Some(name) = stripped.split(['<', '{', ';']).next() {
                            terms.push(name.trim().to_string());
                        }
                    }
                }
            }
        }
    }

    terms.sort();
    terms.dedup();
    terms
}

/// Parse terms defined in CONTEXT.md. Returns the defined term names.
pub fn context_terms(context_path: &Path) -> Vec<String> {
    if let Ok(contents) = fs::read_to_string(context_path) {
        contents
            .lines()
            .filter_map(|line| {
                let line = line.trim();
                if line.starts_with("**") && line.contains("**:") {
                    line.trim_start_matches("**")
                        .split("**:")
                        .next()
                        .map(|s| s.trim().to_string())
                } else {
                    None
                }
            })
            .collect()
    } else {
        Vec::new()
    }
}

/// Check whether a skill body contradicts a CONTEXT.md term.
/// Returns pairs of (term, variant found) for cases where the body uses a
/// different string than the canonical term.
pub fn find_domain_contradictions(body: &str, terms: &[String]) -> Vec<(String, String)> {
    let mut contradictions = Vec::new();
    for term in terms {
        // Very simple heuristic: if the body contains a lowercase variant
        // and the canonical term is mixed-case, flag it.
        let lower = term.to_lowercase();
        if term != &lower && body.contains(&lower) && !body.contains(term) {
            contradictions.push((term.clone(), lower));
        }
    }
    contradictions
}

fn slugify(title: &str) -> String {
    title
        .to_lowercase()
        .replace(|c: char| !c.is_alphanumeric() && c != '-', "-")
        .replace("--", "-")
        .trim_matches('-')
        .to_string()
}

fn next_adr_number(adr_dir: &Path) -> Result<u32> {
    let mut max = 0u32;
    if adr_dir.is_dir() {
        for entry in fs::read_dir(adr_dir)? {
            let name = entry?.file_name();
            let name = name.to_string_lossy();
            if let Some(num_str) = name.split('-').next() {
                if let Ok(num) = num_str.parse::<u32>() {
                    max = max.max(num);
                }
            }
        }
    }
    Ok(max + 1)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn slugify_produces_clean_ids() {
        assert_eq!(
            slugify("Use immutable snapshots"),
            "use-immutable-snapshots"
        );
        assert_eq!(slugify("Foo--bar!!"), "foo-bar");
    }

    #[test]
    fn capture_domain_terms_from_rust_source() {
        let dir = TempDir::new().unwrap();
        fs::create_dir(dir.path().join("src")).unwrap();
        fs::write(
            dir.path().join("src/lib.rs"),
            "pub struct Resolver;\npub fn resolve() {}\npub enum Decision { A }\n",
        )
        .unwrap();
        let terms = capture_domain_terms(dir.path());
        assert!(terms.contains(&"Resolver".into()));
        assert!(terms.contains(&"resolve".into()));
        assert!(terms.contains(&"Decision".into()));
    }

    #[test]
    fn context_terms_parse_bold_definitions() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("CONTEXT.md");
        fs::write(
            &path,
            "## Language\n\n**Application version**:\nThe version string.\n",
        )
        .unwrap();
        let terms = context_terms(&path);
        assert_eq!(terms, vec!["Application version"]);
    }
}

//! `skillastic enroll`: the first-run setup path. Discovers local repos,
//! registers the ones with a `.skillastic` workspace (optionally initializing
//! plain git repos too) for daemon monitoring, installs the binary to a
//! stable location, and wires up autostart via systemd so the daemon
//! survives logout/reboot.

use crate::error::{Result, SkillasticError};
use crate::install;
use crate::model::Config;
use crate::monitor::{self, MonitorRegistry, Scope};
use crate::registry::Registry;
use serde::Serialize;
use std::path::PathBuf;

pub struct EnrollOptions {
    pub scope: Scope,
    pub roots: Vec<PathBuf>,
    pub interval: u64,
    pub init_missing: bool,
    pub max_depth: usize,
    /// Report what would happen without writing or starting anything.
    pub dry_run: bool,
}

#[derive(Debug, Serialize)]
pub struct EnrollReport {
    pub scope: String,
    pub dry_run: bool,
    pub binary_path: Option<String>,
    pub unit_path: Option<String>,
    pub enrolled: Vec<String>,
    pub initialized: Vec<String>,
    pub skipped_no_workspace: Vec<String>,
}

pub fn run(opts: EnrollOptions) -> Result<EnrollReport> {
    match run_inner(&opts) {
        Err(SkillasticError::Io(e))
            if opts.scope.requires_root() && e.kind() == std::io::ErrorKind::PermissionDenied =>
        {
            Err(SkillasticError::Other(
                "system-wide enrollment requires root; re-run with sudo".into(),
            ))
        }
        other => other,
    }
}

fn run_inner(opts: &EnrollOptions) -> Result<EnrollReport> {
    let discovered = monitor::discover_repos(&opts.roots, opts.max_depth)?;

    let mut registry = if opts.dry_run {
        MonitorRegistry::default()
    } else {
        MonitorRegistry::load(opts.scope)?
    };
    let mut enrolled = Vec::new();
    let mut initialized = Vec::new();
    let mut skipped = Vec::new();

    for repo in discovered {
        if !repo.has_skillastic {
            if opts.init_missing {
                if !opts.dry_run {
                    let name = repo
                        .path
                        .file_name()
                        .map(|n| n.to_string_lossy().into_owned())
                        .unwrap_or_else(|| "app".into());
                    let config = Config {
                        app_name: name,
                        ..Default::default()
                    };
                    Registry::init(&repo.path, config)?;
                }
                initialized.push(repo.path.display().to_string());
            } else {
                skipped.push(repo.path.display().to_string());
                continue;
            }
        }
        if !opts.dry_run {
            registry.upsert(&repo.path, opts.interval);
        }
        enrolled.push(repo.path.display().to_string());
    }

    if opts.dry_run {
        return Ok(EnrollReport {
            scope: opts.scope.label().into(),
            dry_run: true,
            binary_path: None,
            unit_path: None,
            enrolled,
            initialized,
            skipped_no_workspace: skipped,
        });
    }

    registry.save(opts.scope)?;
    let bin_path = install::ensure_binary_installed(opts.scope)?;
    let unit_path = install::install_unit(opts.scope, &bin_path)?;
    monitor::resume(opts.scope)?;

    Ok(EnrollReport {
        scope: opts.scope.label().into(),
        dry_run: false,
        binary_path: Some(bin_path.display().to_string()),
        unit_path: Some(unit_path.display().to_string()),
        enrolled,
        initialized,
        skipped_no_workspace: skipped,
    })
}

//! Thin wrapper over the `git` CLI. No libgit2 — same pattern as kaptaind.

use crate::error::{Result, SkillasticError};
use semver::Version;
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use std::process::Command;

const FIELD_SEP: char = '\u{1f}';
const RECORD_SEP: char = '\u{1e}';

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Commit {
    pub hash: String,
    pub subject: String,
    pub body: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ChangeKind {
    Added,
    Modified,
    Deleted,
    Renamed,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FileChange {
    pub kind: ChangeKind,
    pub path: String,
}

pub struct Git {
    root: PathBuf,
}

impl Git {
    /// Open a repo; errors if `root` is not inside a git work tree.
    pub fn open(root: &Path) -> Result<Self> {
        let git = Self {
            root: root.to_path_buf(),
        };
        git.run(&["rev-parse", "--is-inside-work-tree"])?;
        Ok(git)
    }

    pub fn is_repo(root: &Path) -> bool {
        Self::open(root).is_ok()
    }

    /// Short SHA of HEAD.
    pub fn head(&self) -> Result<String> {
        Ok(self
            .run(&["rev-parse", "--short", "HEAD"])?
            .trim()
            .to_string())
    }

    /// Resolve a version/ref name to a commit-ish.
    /// Tries tags `v<semver>` and `<semver>`, then the name verbatim.
    pub fn resolve_ref(&self, name: &str) -> Option<String> {
        let mut candidates = vec![name.to_string()];
        if let Ok(v) = Version::parse(name) {
            candidates.insert(0, format!("v{v}"));
            candidates.insert(1, v.to_string());
        }
        for cand in &candidates {
            if self
                .run(&[
                    "rev-parse",
                    "--verify",
                    "--quiet",
                    &format!("{cand}^{{commit}}"),
                ])
                .is_ok()
            {
                return Some(cand.clone());
            }
        }
        None
    }

    /// Most recent tag reachable from `to` (excluding `to` itself when
    /// `exclude_self` — used to find the *previous* release tag).
    pub fn latest_tag(&self, to: &str, exclude_self: bool) -> Option<String> {
        let target = if exclude_self {
            format!("{to}^")
        } else {
            to.to_string()
        };
        self.run(&["describe", "--tags", "--abbrev=0", &target])
            .ok()
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
    }

    /// Commits in `from..to`, oldest first.
    pub fn log(&self, from: &str, to: &str) -> Result<Vec<Commit>> {
        let format = format!("%H{FIELD_SEP}%s{FIELD_SEP}%b{RECORD_SEP}");
        let out = self.run(&[
            "log",
            "--reverse",
            &format!("--format={format}"),
            &format!("{from}..{to}"),
        ])?;
        let mut commits = Vec::new();
        for record in out.split(RECORD_SEP) {
            let record = record.trim_matches('\n');
            if record.is_empty() {
                continue;
            }
            let mut fields = record.splitn(3, FIELD_SEP);
            let hash = fields.next().unwrap_or_default().trim().to_string();
            let subject = fields.next().unwrap_or_default().trim().to_string();
            let body = fields.next().unwrap_or_default().trim().to_string();
            if !hash.is_empty() {
                commits.push(Commit {
                    hash: hash.chars().take(8).collect(),
                    subject,
                    body,
                });
            }
        }
        Ok(commits)
    }

    /// `git diff --name-status from..to`.
    pub fn diff_name_status(&self, from: &str, to: &str) -> Result<Vec<FileChange>> {
        let out = self.run(&["diff", "--name-status", &format!("{from}..{to}")])?;
        let mut changes = Vec::new();
        for line in out.lines() {
            let mut parts = line.split('\t');
            let (Some(status), Some(path)) = (parts.next(), parts.next()) else {
                continue;
            };
            let kind = match status.chars().next() {
                Some('A') => ChangeKind::Added,
                Some('M') => ChangeKind::Modified,
                Some('D') => ChangeKind::Deleted,
                Some('R') => ChangeKind::Renamed,
                _ => continue,
            };
            // For renames, `path` is the old name and the next field is the new one.
            let path = if kind == ChangeKind::Renamed {
                parts.next().unwrap_or(path).to_string()
            } else {
                path.to_string()
            };
            changes.push(FileChange { kind, path });
        }
        Ok(changes)
    }

    /// File contents at a ref, or None if absent.
    pub fn show_file(&self, ref_: &str, path: &str) -> Option<String> {
        self.run(&["show", &format!("{ref_}:{path}")]).ok()
    }

    pub fn file_exists(&self, ref_: &str, path: &str) -> bool {
        self.run(&["cat-file", "-e", &format!("{ref_}:{path}")])
            .is_ok()
    }

    /// Object type ("blob"/"tree") of a path at a ref, if it exists.
    pub fn object_type(&self, ref_: &str, path: &str) -> Option<String> {
        self.run(&["cat-file", "-t", &format!("{ref_}:{path}")])
            .ok()
            .map(|s| s.trim().to_string())
    }

    /// Top-level entries (files and dirs) of the tree at a ref.
    /// Directory names carry a trailing `/`.
    pub fn ls_tree(&self, ref_: &str) -> Result<Vec<String>> {
        let out = self.run(&["ls-tree", "--name-only", ref_])?;
        Ok(out.lines().map(|l| l.to_string()).collect())
    }

    fn run(&self, args: &[&str]) -> Result<String> {
        let output = Command::new("git")
            .arg("-C")
            .arg(&self.root)
            .args(args)
            .output()?;
        if output.status.success() {
            Ok(String::from_utf8_lossy(&output.stdout).into_owned())
        } else {
            Err(SkillasticError::Git(format!(
                "git {} failed: {}",
                args.join(" "),
                String::from_utf8_lossy(&output.stderr).trim()
            )))
        }
    }
}

//! Installs the daemon so it survives logout/reboot: copies the running
//! binary to a stable location and writes a systemd unit that starts
//! `skillastic monitor resume` at login (user scope) or boot (system scope).

use crate::error::{Result, SkillasticError};
use crate::monitor::Scope;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

/// Set to skip the actual `systemctl` calls in [`install_unit`] — the unit
/// file is still written. Used by tests so they don't register a real
/// systemd unit on the machine running them.
pub const SKIP_SYSTEMCTL_ENV: &str = "SKILLASTIC_SKIP_SYSTEMCTL";

pub fn bin_dir(scope: Scope) -> Result<PathBuf> {
    Ok(match scope {
        Scope::User => user_home()?.join(".local/bin"),
        Scope::System => PathBuf::from("/usr/local/bin"),
    })
}

fn user_home() -> Result<PathBuf> {
    std::env::var("HOME")
        .map(PathBuf::from)
        .map_err(|_| SkillasticError::Other("$HOME is not set".into()))
}

/// Copies the currently running binary into the scope's bin directory,
/// unless it's already running from there. Returns the installed path.
pub fn ensure_binary_installed(scope: Scope) -> Result<PathBuf> {
    let current = std::env::current_exe()?;
    install_binary_at(&current, &bin_dir(scope)?)
}

fn install_binary_at(current: &Path, target_dir: &Path) -> Result<PathBuf> {
    let target = target_dir.join("skillastic");
    let current_canon = current
        .canonicalize()
        .unwrap_or_else(|_| current.to_path_buf());
    let target_canon = target.canonicalize().unwrap_or_else(|_| target.clone());
    if current_canon == target_canon {
        return Ok(target);
    }
    fs::create_dir_all(target_dir)?;
    fs::copy(current, &target)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut perms = fs::metadata(&target)?.permissions();
        perms.set_mode(0o755);
        fs::set_permissions(&target, perms)?;
    }
    Ok(target)
}

fn systemd_unit_dir(scope: Scope) -> Result<PathBuf> {
    Ok(match scope {
        Scope::User => user_home()?.join(".config/systemd/user"),
        Scope::System => PathBuf::from("/etc/systemd/system"),
    })
}

fn unit_contents(scope: Scope, bin_path: &Path) -> String {
    let (target, extra_arg) = match scope {
        Scope::User => ("default.target", ""),
        Scope::System => ("multi-user.target", " --system"),
    };
    format!(
        "[Unit]\n\
Description=Skillastic daemon supervisor\n\
Documentation=https://github.com/elci-group/skillastic\n\
After=network.target\n\
\n\
[Service]\n\
Type=oneshot\n\
RemainAfterExit=yes\n\
ExecStart={} monitor resume{extra_arg}\n\
StandardOutput=journal\n\
StandardError=journal\n\
SyslogIdentifier=skillastic\n\
\n\
[Install]\n\
WantedBy={target}\n",
        bin_path.display(),
    )
}

/// Writes the systemd unit for `scope` and enables + starts it (unless
/// [`SKIP_SYSTEMCTL_ENV`] is set). Returns the unit file path.
pub fn install_unit(scope: Scope, bin_path: &Path) -> Result<PathBuf> {
    let dir = systemd_unit_dir(scope)?;
    fs::create_dir_all(&dir)?;
    let unit_path = dir.join("skillastic.service");
    fs::write(&unit_path, unit_contents(scope, bin_path))?;

    if std::env::var_os(SKIP_SYSTEMCTL_ENV).is_some() {
        return Ok(unit_path);
    }

    run_systemctl(scope, &["daemon-reload"])?;
    run_systemctl(scope, &["enable", "--now", "skillastic.service"])?;
    Ok(unit_path)
}

fn run_systemctl(scope: Scope, args: &[&str]) -> Result<()> {
    let mut cmd = Command::new("systemctl");
    if scope == Scope::User {
        cmd.arg("--user");
    }
    cmd.args(args);
    let output = cmd
        .output()
        .map_err(|e| SkillasticError::Other(format!("failed to run systemctl: {e}")))?;
    if !output.status.success() {
        return Err(SkillasticError::Other(format!(
            "systemctl {} failed: {}",
            args.join(" "),
            String::from_utf8_lossy(&output.stderr).trim()
        )));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn user_unit_targets_login_and_omits_system_flag() {
        let contents = unit_contents(Scope::User, Path::new("/home/x/.local/bin/skillastic"));
        assert!(contents.contains("ExecStart=/home/x/.local/bin/skillastic monitor resume\n"));
        assert!(contents.contains("WantedBy=default.target"));
        assert!(!contents.contains("--system"));
    }

    #[test]
    fn system_unit_targets_boot_and_passes_system_flag() {
        let contents = unit_contents(Scope::System, Path::new("/usr/local/bin/skillastic"));
        assert!(contents.contains("ExecStart=/usr/local/bin/skillastic monitor resume --system\n"));
        assert!(contents.contains("WantedBy=multi-user.target"));
    }

    #[test]
    fn installs_binary_into_target_dir_with_exec_bit() {
        let dir = TempDir::new().unwrap();
        let fake_current = dir.path().join("source-binary");
        fs::write(&fake_current, b"#!/bin/sh\necho hi\n").unwrap();
        let target_dir = dir.path().join("bin");

        let installed = install_binary_at(&fake_current, &target_dir).unwrap();
        assert_eq!(installed, target_dir.join("skillastic"));
        assert!(installed.is_file());

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = fs::metadata(&installed).unwrap().permissions().mode();
            assert_eq!(mode & 0o777, 0o755);
        }
    }

    #[test]
    fn skips_copy_when_already_installed() {
        let dir = TempDir::new().unwrap();
        let target_dir = dir.path().join("bin");
        fs::create_dir_all(&target_dir).unwrap();
        let target = target_dir.join("skillastic");
        fs::write(&target, b"already here").unwrap();

        let installed = install_binary_at(&target, &target_dir).unwrap();
        assert_eq!(installed, target);
        assert_eq!(fs::read(&target).unwrap(), b"already here");
    }
}

