/// Skillastic — adaptive skill runtime.
///
/// Keeps AI-agent skills compatible with the application they describe:
/// deterministic version resolution, commit archaeology, context capture,
/// and skill migration with lineage.
#[derive(Parser)]
#[command(name = "skillastic", version, about)]
struct Cli {
    /// Emit machine-readable JSON.
    #[arg(long, global = true)]
    json: bool,

    /// Override the application version (semver) instead of auto-detecting.
    #[arg(long, global = true, value_name = "SEMVER")]
    app_version: Option<String>,

    #[command(subcommand)]
    command: Command,
}

#[derive(Clone, ValueEnum)]
enum InvocationArg {
    User,
    Model,
    Both,
}

impl From<InvocationArg> for SkillInvocation {
    fn from(arg: InvocationArg) -> Self {
        match arg {
            InvocationArg::User => SkillInvocation::UserInvoked,
            InvocationArg::Model => SkillInvocation::ModelInvoked,
            InvocationArg::Both => SkillInvocation::Both,
        }
    }
}

#[derive(Subcommand)]
enum Command {
    /// Initialize a .skillastic workspace in the current project.
    Init {
        /// Application name (defaults to the directory name).
        #[arg(long)]
        app_name: Option<String>,
        /// Project-type template to seed (rust, node, python, go).
        #[arg(long)]
        template: Option<String>,
    },

    /// Configure this repo for the Skillastic skills (issue tracker, triage labels, domain docs).
    Setup {
        /// Skip interactive prompts and use defaults.
        #[arg(long)]
        non_interactive: bool,
        /// Issue tracker provider when using --non-interactive.
        #[arg(long)]
        issue_tracker: Option<String>,
    },

    /// Register a new skill.
    Add {
        /// Skill name, e.g. "frontend-react".
        name: String,
        /// Initial skill version.
        #[arg(long)]
        version: String,
        /// Compatible app range(s), e.g. ">=2.1.0, <3.0.0". Repeatable.
        #[arg(long, required = true)]
        compatible: Vec<String>,
        /// Markdown file with the skill's instruction body.
        #[arg(long)]
        body: Option<PathBuf>,
        /// Built-in skill template to use as the body.
        #[arg(long)]
        template: Option<String>,
        /// Mark the skill verified against the current app version.
        #[arg(long)]
        verify: bool,
        /// Bucket for the skill.
        #[arg(long, value_enum, default_value = "core")]
        bucket: String,
        /// Who can invoke the skill.
        #[arg(long, value_enum, default_value = "both")]
        invocation: InvocationArg,
        /// Other skills this skill requires. Repeatable.
        #[arg(long)]
        requires: Vec<String>,
    },

    /// Remove a skill.
    Remove {
        /// Skill name.
        name: String,
    },

    /// List registered skills.
    List,

    /// Show one skill in full.
    Show {
        /// Skill name.
        name: String,
        /// Render the human-facing docs page instead of raw metadata.
        #[arg(long)]
        docs: bool,
    },

    /// Version-resolver report for all skills vs. the current app version.
    Status,

    /// Commit-chain analysis between two app versions.
    Archaeology {
        /// Start version/ref (default: tag before --to).
        #[arg(long)]
        from: Option<String>,
        /// End version/ref (default: HEAD).
        #[arg(long)]
        to: Option<String>,
    },

    /// Capture the current codebase context fingerprint.
    Capture {
        /// Extract candidate domain terms from source files.
        #[arg(long)]
        domain: bool,
    },

    /// Migrate a skill (or --all) to the current app version.
    Migrate {
        /// Skill name; omit with --all.
        name: Option<String>,
        /// Migrate every skill the resolver marks `migrate`.
        #[arg(long)]
        all: bool,
        /// Compute and print the delta without writing anything.
        #[arg(long)]
        dry_run: bool,
    },

    /// Mark a skill verified against the current app version.
    Verify {
        /// Skill name.
        name: String,
    },

    /// Show a skill's lineage chain and mutation history.
    History {
        /// Skill name.
        name: String,
    },

    /// Run the skillastic daemon (poll for app changes, auto-resolve/migrate).
    Daemon {
        /// Poll interval in seconds.
        #[arg(long, default_value_t = 60)]
        interval: u64,
    },

    /// Show recent daemon events recorded in the workspace state.
    Events,

    /// Audit project roots for missing or incomplete .skillastic workspaces.
    Audit {
        /// Directory to scan (defaults to the current directory).
        #[arg(long, default_value = ".")]
        root: PathBuf,
        /// Additional project-source directory; repeat for multiple sources.
        #[arg(long = "source")]
        sources: Vec<PathBuf>,
        /// Ask Groq to prioritize deterministic findings using bound context.
        #[arg(long)]
        infer: bool,
        /// Groq model used for advisory prioritization.
        #[arg(long, default_value = "llama-3.1-8b-instant")]
        model: String,
    },

    /// List and validate the promoted skill set.
    Promoted,

    /// Lint the workspace and its skills.
    Lint {
        /// Also run domain-language checks against CONTEXT.md.
        #[arg(long)]
        domain: bool,
    },

    /// Check workspace health and report actionable fixes.
    Doctor,

    /// Generate or update the project's CONTEXT.md domain glossary.
    DomainModel,

    /// Create a new architectural decision record.
    Adr {
        /// Short title for the decision.
        title: String,
    },

    /// Generate or render human-facing docs pages for skills.
    Docs {
        #[command(subcommand)]
        action: DocsAction,
    },

    /// Search registered skills by name, bucket, or body text.
    Search {
        /// Query string.
        query: String,
    },

    /// First-time setup: discover local repos, install the daemon, and make
    /// sure it survives logout/reboot.
    Enroll {
        /// Monitor every user's repos and autostart at boot instead of
        /// login. Requires root.
        #[arg(long)]
        system: bool,
        /// Directory to scan for repos (repeatable). Defaults to $HOME for
        /// user scope, or /home for system scope.
        #[arg(long = "root")]
        roots: Vec<PathBuf>,
        /// Poll interval for each enrolled daemon, in seconds.
        #[arg(long, default_value_t = 300)]
        interval: u64,
        /// Also run `skillastic init` for discovered git repos that have no
        /// .skillastic workspace yet, so they can be enrolled too.
        #[arg(long)]
        init_missing: bool,
        /// Max directory depth to scan below each root.
        #[arg(long, default_value_t = 6)]
        max_depth: usize,
        /// Report what would happen without installing or starting anything.
        #[arg(long)]
        dry_run: bool,
    },

    /// Manage the multi-repo daemon supervisor (used by the systemd unit
    /// `enroll` installs; rarely invoked directly).
    Monitor {
        /// Operate on the system-wide registry instead of the per-user one.
        #[arg(long, global = true)]
        system: bool,
        #[command(subcommand)]
        action: MonitorAction,
    },

    /// Create (or reuse) a .skillastic workspace for one or more projects
    /// and index them for daemon monitoring.
    Register {
        /// Project directories to register (defaults to the current
        /// directory). With --mandatory, treated as extra scan roots.
        paths: Vec<PathBuf>,
        /// Recursively scan the home directory (or /home for --system) plus
        /// the roots in the user's global config
        /// (~/.config/skillastic/config.json), registering every project
        /// found. Opt a directory out with a .skillasticignore file in it.
        #[arg(long)]
        mandatory: bool,
        /// Index into the system-wide registry instead of the per-user one.
        #[arg(long)]
        system: bool,
        /// Poll interval for each registered daemon, in seconds.
        #[arg(long, default_value_t = 300)]
        interval: u64,
        /// Max directory depth to scan below each root (--mandatory only).
        #[arg(long, default_value_t = 6)]
        max_depth: usize,
        /// Report what would happen without writing or starting anything.
        #[arg(long)]
        dry_run: bool,
    },
}

#[derive(Subcommand)]
enum MonitorAction {
    /// Register a project for monitoring (defaults to the current directory).
    Add {
        path: Option<PathBuf>,
        /// Poll interval in seconds.
        #[arg(long, default_value_t = 300)]
        interval: u64,
    },
    /// Unregister a project (defaults to the current directory).
    Remove { path: Option<PathBuf> },
    /// Show all registered projects and whether their daemon is running.
    List,
    /// Enable monitoring for a project (defaults to the current directory).
    Enable { path: Option<PathBuf> },
    /// Disable monitoring for a project (defaults to the current directory).
    Disable { path: Option<PathBuf> },
    /// Start daemons for all enabled, not-running projects.
    Resume,
}

#[derive(Subcommand)]
enum DocsAction {
    /// Generate a docs page for a skill.
    Generate {
        /// Skill name.
        name: String,
    },
}

fn main() -> ExitCode {
    let cli = Cli::parse();
    let project_root = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    match run(cli, &project_root) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

fn run(cli: Cli, project_root: &Path) -> Result<()> {
    let json = cli.json;
    let app_version_override = cli.app_version.as_deref();

    match cli.command {
        Command::Init { app_name, template } => {
            let name = app_name.unwrap_or_else(|| {
                project_root
                    .file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_else(|| "app".into())
            });
            let pinned = match app_version_override {
                Some(raw) => Some(appver::parse(raw)?),
                None => None,
            };
            let config = Config {
                app_name: name.clone(),
                app_version: pinned,
                ..Default::default()
            };
            let registry = Registry::init(project_root, config)?;

            // Seed project-type template skill if requested.
            let seeded_template = template.as_deref();
            if let Some(template_name) = seeded_template {
                if let Some(body) = templates::project_template_body(template_name) {
                    let mut skill = Skill::new(
                        template_name,
                        appver::parse("1.0.0")?,
                        vec![],
                        app_version_override
                            .map(appver::parse)
                            .transpose()?
                            .unwrap_or_else(|| semver::Version::new(0, 0, 0)),
                    );
                    skill.invocation = SkillInvocation::UserInvoked;
                    skill.bucket = "core".into();
                    registry.add_skill(&skill, body)?;
                } else {
                    return Err(SkillasticError::Other(format!(
                        "unknown template '{template_name}'; choose one of: {}",
                        templates::PROJECT_TEMPLATES.join(", ")
                    )));
                }
            }

            if json {
                print_json(&serde_json::json!({
                    "initialized": registry.root(),
                    "app_name": name,
                }));
            } else {
                println!(
                    "Initialized skillastic workspace for '{name}' in {}",
                    registry.root().display()
                );
                if let Some(template_name) = seeded_template {
                    println!("Seeded template skill: {template_name}");
                }
            }
        }

        Command::Setup {
            non_interactive,
            issue_tracker,
        } => {
            let registry = open_registry(project_root)?;
            setup::run(
                &registry,
                setup::SetupOptions {
                    non_interactive,
                    issue_tracker,
                },
            )?;
            if !json {
                println!("Setup complete. See .skillastic/agents/");
            }
        }

        Command::Add {
            name,
            version,
            compatible,
            body,
            template,
            verify: verify_now,
            bucket,
            invocation,
            requires,
        } => {
            let registry = open_registry(project_root)?;
            let config = registry.config()?;
            let app_version = appver::detect(project_root, &config, app_version_override)?;
            for range in &compatible {
                parse_req(range)?; // fail fast on garbage ranges
            }

            let body_text = match (body, template) {
                (Some(path), None) => std::fs::read_to_string(path)?,
                (None, Some(template_name)) => {
                    templates::workflow_skill_body(&template_name)
                        .ok_or_else(|| {
                            SkillasticError::Other(format!(
                                "unknown template '{template_name}'; choose one of: ask-skillastic, tdd, code-review, diagnosing-bugs, to-spec, to-tickets, implement, triage, handoff"
                            ))
                        })?
                        .to_string()
                }
                (Some(_), Some(_)) => {
                    return Err(SkillasticError::Other(
                        "pass --body or --template, not both".into(),
                    ))
                }
                (None, None) => format!("# {name}\n\nDescribe how to work with this subsystem.\n"),
            };

            let mut skill = Skill::new(
                &name,
                appver::parse(&version)?,
                compatible,
                app_version.clone(),
            );
            skill.context = Capture::scan(project_root)?;
            skill.bucket = bucket;
            skill.invocation = invocation.into();
            skill.requires = requires;
            registry.add_skill(&skill, &body_text)?;
            if verify_now {
                skill = verify(&registry, &name, &app_version)?;
            }
            registry.regenerate_bucket_readmes()?;
            if json {
                print_json(&skill);
            } else {
                println!(
                    "Registered skill '{}' v{} against app {app_version} (status: {})",
                    skill.name, skill.skill_version, skill.status
                );
            }
        }

        Command::Remove { name } => {
            let registry = open_registry(project_root)?;
            registry.remove_skill(&name)?;
            registry.regenerate_bucket_readmes()?;
            if !json {
                println!("Removed skill '{name}'");
            }
        }

        Command::List => {
            let registry = open_registry(project_root)?;
            let skills = registry.list_skills()?;
            if json {
                print_json(&skills);
            } else if skills.is_empty() {
                println!("No skills registered. Use `skillastic add`.");
            } else {
                let rows = skills
                    .iter()
                    .map(|s| {
                        vec![
                            s.name.clone(),
                            s.skill_version.to_string(),
                            s.bucket.clone(),
                            s.invocation.to_string(),
                            s.status.to_string(),
                            format!("{:.2}", s.confidence),
                            s.compatible_apps.join(" | "),
                            s.verified_app_version.to_string(),
                        ]
                    })
                    .collect();
                print!(
                    "{}",
                    table(
                        &[
                            "SKILL",
                            "VERSION",
                            "BUCKET",
                            "INVOCATION",
                            "STATUS",
                            "CONF",
                            "COMPATIBLE APPS",
                            "VERIFIED APP"
                        ],
                        rows,
                    )
                );
            }
        }

        Command::Show { name, docs } => {
            let registry = open_registry(project_root)?;
            if docs {
                let page = docs::render(&registry, &name)?;
                println!("{page}");
            } else {
                let skill = registry.load_skill(&name)?;
                if json {
                    print_json(&skill);
                } else {
                    println!("{}", serde_json::to_string_pretty(&skill)?);
                    let body = registry.skill_body(&skill)?;
                    println!("\n--- body ({}) ---\n{body}", skill.body_path);
                }
            }
        }

        Command::Status => {
            let registry = open_registry(project_root)?;
            let config = registry.config()?;
            let app_version = appver::detect(project_root, &config, app_version_override)?;
            let skills = registry.list_skills()?;
            let arch = Archaeology::new(project_root).ok();
            let resolver = Resolver::new(arch.as_ref(), &app_version);
            let resolutions = resolver.resolve_all(&skills, &app_version)?;

            // Reflect decisions onto stored skill statuses.
            for res in &resolutions {
                registry.apply_resolution(res)?;
            }

            if json {
                print_json(&serde_json::json!({
                    "app_version": app_version,
                    "resolutions": resolutions,
                }));
            } else {
                println!("App version: {app_version}\n");
                if resolutions.is_empty() {
                    println!("No skills registered.");
                } else {
                    let rows = resolutions
                        .iter()
                        .map(|r| {
                            vec![
                                r.skill.clone(),
                                r.from_app.to_string(),
                                r.to_app.to_string(),
                                r.decision.to_string(),
                                r.reason.clone(),
                            ]
                        })
                        .collect();
                    print!(
                        "{}",
                        table(&["SKILL", "FROM", "TO", "DECISION", "REASON"], rows)
                    );
                }
            }
        }

        Command::Archaeology { from, to } => {
            let arch = Archaeology::new(project_root).map_err(|_| {
                SkillasticError::Other("not a git repository; archaeology unavailable".into())
            })?;
            let to_ref = match to {
                Some(t) => t,
                None => "HEAD".into(),
            };
            let from_ref = match from {
                Some(f) => f,
                None => arch.previous_tag(&to_ref).ok_or_else(|| {
                    SkillasticError::Other("no earlier tag found; pass --from".into())
                })?,
            };
            let chain = arch.analyze(&from_ref, &to_ref)?;
            if json {
                print_json(&chain);
            } else {
                println!("Commit chain {} -> {}\n", chain.from_ref, chain.to_ref);
                println!("Commits: {}", chain.commits.len());
                for c in &chain.commits {
                    println!("  {} {}", c.hash, c.subject);
                }
                if !chain.breaking.is_empty() {
                    println!("\nBreaking:");
                    for c in &chain.breaking {
                        println!("  {} {}", c.hash, c.subject);
                    }
                }
                if chain.dep_changes.any() {
                    println!("\nDependencies:");
                    for (n, v) in &chain.dep_changes.added {
                        println!("  + {n} ({v})");
                    }
                    for (n, v) in &chain.dep_changes.removed {
                        println!("  - {n} ({v})");
                    }
                    for (n, (o, new)) in &chain.dep_changes.changed {
                        println!("  ~ {n}: {o} -> {new}");
                    }
                }
                if !chain.toolchain_changes.appeared.is_empty()
                    || !chain.toolchain_changes.disappeared.is_empty()
                {
                    println!("\nToolchains:");
                    for t in &chain.toolchain_changes.appeared {
                        println!("  + {t}");
                    }
                    for t in &chain.toolchain_changes.disappeared {
                        println!("  - {t}");
                    }
                }
            }
        }

        Command::Capture { domain } => {
            if domain {
                let terms = domain::capture_domain_terms(project_root);
                if json {
                    print_json(&serde_json::json!({ "domain_terms": terms }));
                } else {
                    println!("Candidate domain terms:");
                    for term in terms {
                        println!("  - {term}");
                    }
                }
            } else {
                let fp = Capture::scan(project_root)?;
                if json {
                    print_json(&fp);
                } else {
                    println!("{}", serde_json::to_string_pretty(&fp)?);
                }
            }
        }

        Command::Migrate { name, all, dry_run } => {
            let registry = open_registry(project_root)?;
            let config = registry.config()?;
            let app_version = appver::detect(project_root, &config, app_version_override)?;
            let migrator = Migrator::new(&registry);

            let targets: Vec<String> =
                if all {
                    let arch = Archaeology::new(project_root).ok();
                    let resolver = Resolver::new(arch.as_ref(), &app_version);
                    resolver
                        .resolve_all(&registry.list_skills()?, &app_version)?
                        .into_iter()
                        .filter(|r| r.decision == Decision::Migrate)
                        .map(|r| r.skill)
                        .collect()
                } else {
                    vec![name.ok_or_else(|| {
                        SkillasticError::Other("pass a skill name or --all".into())
                    })?]
                };

            if targets.is_empty() {
                println!("Nothing to migrate.");
                return Ok(());
            }

            let mut outcomes = Vec::new();
            for target in &targets {
                let outcome = migrator.migrate(target, &app_version, dry_run)?;
                if json {
                    outcomes.push(outcome);
                } else {
                    println!(
                        "{}{}: skill {} -> {} (app {} -> {})",
                        if dry_run { "[dry-run] " } else { "" },
                        outcome.skill,
                        outcome.from_skill_version,
                        outcome.to_skill_version,
                        outcome.from_app,
                        outcome.to_app
                    );
                    println!("  reason: {}", outcome.delta.reason());
                    if let Some(dir) = &outcome.snapshot_dir {
                        println!("  snapshot: {}", dir.display());
                    }
                    if dry_run {
                        print!("{}", outcome.delta.to_markdown());
                    }
                }
            }
            if json {
                print_json(&outcomes);
            }
        }

        Command::Verify { name } => {
            let registry = open_registry(project_root)?;
            let config = registry.config()?;
            let app_version = appver::detect(project_root, &config, app_version_override)?;
            let skill = verify(&registry, &name, &app_version)?;
            if json {
                print_json(&skill);
            } else {
                println!(
                    "Verified '{}' v{} against app {app_version} (confidence: {:.2})",
                    skill.name, skill.skill_version, skill.confidence
                );
            }
        }

        Command::History { name } => {
            let registry = open_registry(project_root)?;
            let skill = registry.load_skill(&name)?;
            if json {
                let mut chain = vec![skill.clone()];
                let mut cursor = skill.parent.clone();
                while let Some(id) = cursor {
                    match registry.load_snapshot(&id) {
                        Ok((parent, _)) => {
                            cursor = parent.parent.clone();
                            chain.push(parent);
                        }
                        Err(_) => break,
                    }
                }
                print_json(&chain);
            } else {
                println!("Lineage of '{}':", name);
                let mut current_id = skill.id();
                let mut cursor = Some(skill.clone());
                while let Some(node) = cursor {
                    let marker = if node.id() == current_id {
                        " (current)"
                    } else {
                        ""
                    };
                    println!("  {}{}", node.id(), marker);
                    if !node.mutation_history.is_empty() {
                        for m in &node.mutation_history {
                            println!(
                                "    [{}] {} — {}",
                                m.timestamp.format("%Y-%m-%d"),
                                m.commit,
                                m.reason
                            );
                        }
                    }
                    cursor = match &node.parent {
                        Some(id) if *id != current_id => {
                            current_id = id.clone();
                            registry.load_snapshot(id).ok().map(|(s, _)| s)
                        }
                        _ => None,
                    };
                }
            }
        }

        Command::Daemon { interval } => {
            let registry = open_registry(project_root)?;
            Daemon::new(&registry, interval).run()?;
        }

        Command::Events => {
            let registry = open_registry(project_root)?;
            let events = recent_events(&registry)?;
            if json {
                print_json(&events);
            } else if events.is_empty() {
                println!("No daemon events recorded yet.");
            } else {
                for event in &events {
                    println!("{event}");
                }
            }
        }

        Command::Audit {
            root,
            sources,
            infer,
            model,
        } => {
            let root = if root.is_absolute() {
                root
            } else {
                project_root.join(root)
            };
            let sources = sources
                .into_iter()
                .map(|source| {
                    if source.is_absolute() {
                        source
                    } else {
                        project_root.join(source)
                    }
                })
                .collect::<Vec<_>>();
            let report = audit::run(&root, &sources, infer, &model)?;
            if json {
                print_json(&report);
            } else {
                println!(
                    "Audited {} project(s) under {}",
                    report.totals.projects, report.root
                );
                for project in &report.projects {
                    println!(
                        "{:14} {}",
                        format!("{:?}", project.workspace.state).to_lowercase(),
                        project.path
                    );
                    for reason in &project.workspace.reasons {
                        println!("  - {reason}");
                    }
                }
                if let Some(inference) = report.inference {
                    println!("Groq inference: {}", inference.status);
                }
            }
        }

        Command::Promoted => {
            let registry = open_registry(project_root)?;
            let set = registry.promoted()?;
            let skills = registry.list_skills()?;
            let names: std::collections::HashSet<String> =
                skills.iter().map(|s| s.name.clone()).collect();
            let missing: Vec<&String> = set.skills.iter().filter(|s| !names.contains(*s)).collect();
            if json {
                print_json(&serde_json::json!({
                    "skills": set.skills,
                    "missing": missing,
                }));
            } else {
                println!("Promoted skills:");
                for name in &set.skills {
                    let status = if names.contains(name) {
                        ""
                    } else {
                        " [missing]"
                    };
                    println!("  - {name}{status}");
                }
                if !missing.is_empty() {
                    return Err(SkillasticError::Other(format!(
                        "{} promoted skill(s) are not registered",
                        missing.len()
                    )));
                }
            }
        }

        Command::Lint { domain } => {
            let registry = open_registry(project_root)?;
            let report = lint::lint(&registry, domain)?;
            if json {
                print_json(&report.violations);
            } else if report.violations.is_empty() {
                println!("No lint violations.");
            } else {
                println!("Lint violations:");
                for v in &report.violations {
                    println!("  - {v}");
                }
            }
        }

        Command::Doctor => {
            let registry = open_registry(project_root)?;
            let diagnosis = doctor::diagnose(&registry)?;
            if json {
                print_json(&serde_json::json!({
                    "healthy": diagnosis.healthy,
                    "findings": diagnosis.findings,
                }));
            } else if diagnosis.healthy {
                println!("Workspace is healthy.");
            } else {
                println!("Workspace issues:");
                for finding in &diagnosis.findings {
                    println!("  - {finding}");
                }
            }
        }

        Command::DomainModel => {
            let registry = open_registry(project_root)?;
            let path = domain::ensure_context_md(&registry)?;
            if !json {
                println!("Domain glossary: {}", path.display());
                println!("Edit CONTEXT.md to add terms, then run `skillastic lint --domain`.");
            }
        }

        Command::Adr { title } => {
            let registry = open_registry(project_root)?;
            let path = domain::create_adr(&registry, &title)?;
            if !json {
                println!("Created ADR: {}", path.display());
            }
        }

        Command::Docs { action } => match action {
            DocsAction::Generate { name } => {
                let registry = open_registry(project_root)?;
                let path = docs::generate(&registry, &name)?;
                if !json {
                    println!("Generated docs page: {}", path.display());
                }
            }
        },

        Command::Enroll {
            system,
            roots,
            interval,
            init_missing,
            max_depth,
            dry_run,
        } => {
            let scope = if system { Scope::System } else { Scope::User };
            let roots = if roots.is_empty() {
                vec![monitor::default_scan_root(scope)?]
            } else {
                roots
            };
            let report = enroll::run(enroll::EnrollOptions {
                scope,
                roots,
                interval,
                init_missing,
                max_depth,
                dry_run,
            })?;
            if json {
                print_json(&report);
            } else {
                let verb = if dry_run { "Would enroll" } else { "Enrolled" };
                println!(
                    "{verb} {} project(s) for {} monitoring.",
                    report.enrolled.len(),
                    report.scope
                );
                if !report.initialized.is_empty() {
                    println!("Initialized new workspaces:");
                    for p in &report.initialized {
                        println!("  - {p}");
                    }
                }
                if !report.skipped_no_workspace.is_empty() {
                    println!(
                        "Skipped (no .skillastic workspace; re-run with --init-missing, or `skillastic init` there):"
                    );
                    for p in &report.skipped_no_workspace {
                        println!("  - {p}");
                    }
                }
                if let (Some(bin), Some(unit)) = (&report.binary_path, &report.unit_path) {
                    println!("Daemon binary: {bin}");
                    println!("Systemd unit:  {unit}");
                    let when = match scope {
                        Scope::User => "at your next login",
                        Scope::System => "at boot",
                    };
                    println!("The daemon is running now, and will restart automatically {when}.");
                }
            }
        }

        Command::Monitor { system, action } => {
            let scope = if system { Scope::System } else { Scope::User };
            match action {
                MonitorAction::Add { path, interval } => {
                    let path = resolve_monitor_path(path, project_root);
                    let mut registry = MonitorRegistry::load(scope)?;
                    registry.upsert(&path, interval);
                    registry.save(scope)?;
                    if !json {
                        println!("Monitoring {}", path.display());
                    }
                }
                MonitorAction::Remove { path } => {
                    let path = resolve_monitor_path(path, project_root);
                    let mut registry = MonitorRegistry::load(scope)?;
                    let removed = registry.remove(&path);
                    registry.save(scope)?;
                    if !json {
                        if removed {
                            println!("Removed {}", path.display());
                        } else {
                            println!("Not monitored: {}", path.display());
                        }
                    }
                }
                MonitorAction::Enable { path } => {
                    let path = resolve_monitor_path(path, project_root);
                    let mut registry = MonitorRegistry::load(scope)?;
                    registry.set_enabled(&path, true)?;
                    registry.save(scope)?;
                    if !json {
                        println!("Enabled {}", path.display());
                    }
                }
                MonitorAction::Disable { path } => {
                    let path = resolve_monitor_path(path, project_root);
                    let mut registry = MonitorRegistry::load(scope)?;
                    registry.set_enabled(&path, false)?;
                    registry.save(scope)?;
                    if !json {
                        println!("Disabled {}", path.display());
                    }
                }
                MonitorAction::List => {
                    let registry = MonitorRegistry::load(scope)?;
                    if json {
                        print_json(&registry);
                    } else if registry.projects.is_empty() {
                        println!(
                            "No projects registered. Use `skillastic enroll` or `skillastic monitor add`."
                        );
                    } else {
                        let rows = registry
                            .projects
                            .values()
                            .map(|p| {
                                let pid = monitor::running_daemon_pid(&p.path);
                                vec![
                                    p.path.display().to_string(),
                                    if p.enabled {
                                        "enabled".into()
                                    } else {
                                        "disabled".into()
                                    },
                                    p.interval.to_string(),
                                    pid.map(|id| format!("running ({id})"))
                                        .unwrap_or_else(|| "stopped".into()),
                                ]
                            })
                            .collect();
                        print!("{}", table(&["PATH", "STATE", "INTERVAL", "DAEMON"], rows));
                    }
                }
                MonitorAction::Resume => {
                    let outcomes = monitor::resume(scope)?;
                    if json {
                        print_json(&outcomes);
                    } else {
                        for outcome in &outcomes {
                            println!("{}", outcome.describe());
                        }
                    }
                }
            }
        }

        Command::Search { query } => {
            let registry = open_registry(project_root)?;
            let hits = search::search(&registry, &query)?;
            if json {
                print_json(&hits);
            } else if hits.is_empty() {
                println!("No skills matched '{query}'.");
            } else {
                print!("{}", search::hits_to_table(&hits));
            }
        }

        Command::Register {
            paths,
            mandatory,
            system,
            interval,
            max_depth,
            dry_run,
        } => {
            let scope = if system { Scope::System } else { Scope::User };
            // Targeted mode (no --mandatory) registers the current directory
            // when no path is given; --mandatory decides its own roots.
            let paths = if paths.is_empty() && !mandatory {
                vec![project_root.to_path_buf()]
            } else {
                paths
            };
            let report = register::run(register::RegisterOptions {
                paths,
                mandatory,
                scope,
                interval,
                max_depth,
                dry_run,
            })?;
            if json {
                print_json(&report);
            } else {
                let verb = if dry_run {
                    "Would register"
                } else {
                    "Registered"
                };
                println!("{verb} {} project(s).", report.registered.len());
                if !report.initialized.is_empty() {
                    println!("Initialized new workspaces:");
                    for p in &report.initialized {
                        println!("  - {p}");
                    }
                }
                if !report.already_indexed.is_empty() {
                    println!("Already indexed (interval refreshed):");
                    for p in &report.already_indexed {
                        println!("  - {p}");
                    }
                }
            }
        }
    }
    Ok(())
}

fn open_registry(project_root: &Path) -> Result<Registry> {
    Registry::open(project_root)
}

fn resolve_monitor_path(path: Option<PathBuf>, project_root: &Path) -> PathBuf {
    let path = path.unwrap_or_else(|| project_root.to_path_buf());
    path.canonicalize().unwrap_or(path)
}

fn print_json<T: Serialize>(value: &T) {
    match serde_json::to_string_pretty(value) {
        Ok(s) => println!("{s}"),
        Err(e) => eprintln!("error serializing output: {e}"),
    }
}

/// Minimal padded-column table renderer.
fn table(headers: &[&str], rows: Vec<Vec<String>>) -> String {
    let mut widths: Vec<usize> = headers.iter().map(|h| h.len()).collect();
    for row in &rows {
        for (i, cell) in row.iter().enumerate() {
            if i < widths.len() {
                widths[i] = widths[i].max(cell.len());
            }
        }
    }
    let render = |cells: &[String]| -> String {
        cells
            .iter()
            .enumerate()
            .map(|(i, c)| format!("{:<width$}", c, width = widths[i]))
            .collect::<Vec<_>>()
            .join("  ")
            .trim_end()
            .to_string()
    };
    let header_cells: Vec<String> = headers.iter().map(|h| h.to_string()).collect();
    let mut out = render(&header_cells);
    out.push('\n');
    out.push_str(
        &widths
            .iter()
            .map(|w| "-".repeat(*w))
            .collect::<Vec<_>>()
            .join("  "),
    );
    out.push('\n');
    for row in rows {
        out.push_str(&render(&row));
        out.push('\n');
    }
    out
}

//! Skill Migration Engine: the deterministic pipeline that brings a skill
//! from its verified app version to the current one.
//!
//! Pipeline: snapshot → commit archaeology → context capture → delta →
//! append-only patch (or optional LLM rewrite) → version bump + lineage.

use crate::archaeology::{Archaeology, CommitChain};
use crate::capture::Capture;
use crate::delta::ContextDelta;
use crate::error::{Result, SkillasticError};
use crate::git::Git;
use crate::model::{MutationRecord, Skill, SkillStatus, VersionDelta};
use crate::registry::Registry;
use chrono::Utc;
use semver::Version;
use serde::Serialize;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

/// Confidence assigned after an unreviewed auto-migration.
pub const MIGRATED_CONFIDENCE: f64 = 0.70;
/// Confidence assigned by `skillastic verify`.
pub const VERIFIED_CONFIDENCE: f64 = 0.95;

#[derive(Debug, Serialize)]
pub struct MigrationOutcome {
    pub skill: String,
    pub from_skill_version: Version,
    pub to_skill_version: Version,
    pub parent: String,
    pub from_app: Version,
    pub to_app: Version,
    pub delta: ContextDelta,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub snapshot_dir: Option<PathBuf>,
    pub llm_used: bool,
    pub dry_run: bool,
}

pub struct Migrator<'a> {
    registry: &'a Registry,
}

impl<'a> Migrator<'a> {
    pub fn new(registry: &'a Registry) -> Self {
        Self { registry }
    }

    /// Run the migration pipeline for one skill. With `dry_run`, computes
    /// the full outcome but writes nothing (no snapshot, no saves).
    pub fn migrate(&self, name: &str, to_app: &Version, dry_run: bool) -> Result<MigrationOutcome> {
        let mut skill = self.registry.load_skill(name)?;
        let body = self.registry.skill_body(&skill)?;
        let from_app = skill.verified_app_version.clone();
        let bump = VersionDelta::between(&from_app, to_app);
        if bump == VersionDelta::Same {
            return Err(SkillasticError::Other(format!(
                "skill '{name}' already targets app {to_app}; nothing to migrate"
            )));
        }
        let project_root = self.registry.project_root();

        // 1. Snapshot the existing skill (spec: capture instructions,
        //    examples, failure modes, tool assumptions, prior mutations).
        let snapshot_dir = if dry_run {
            None
        } else {
            Some(self.registry.snapshot(&skill)?)
        };

        // 2. Commit-chain analysis (best effort; capture-only fallback when
        //    the project isn't a git repo or refs don't resolve).
        let chain = self.commit_chain(&project_root, &from_app, to_app);

        // 3. Context delta generation inputs: old fingerprint from the git
        //    ref when available, else the fingerprint stored on the skill.
        let new_fp = Capture::scan(&project_root)?;
        let old_fp = match &chain {
            Some(c) => Git::open(&project_root)
                .and_then(|git| Capture::scan_ref(&git, &c.from_ref))
                .unwrap_or_else(|_| skill.context.clone()),
            None => skill.context.clone(),
        };

        let delta = ContextDelta::build(
            chain.as_ref(),
            from_app.clone(),
            to_app.clone(),
            &old_fp,
            &new_fp,
        );

        // 4. Patch: deterministic append-only notes, or the optional LLM
        //    adapter when `llm_command` is configured.
        let config = self.registry.config()?;
        let (new_body, llm_used) = match config.llm_command.as_deref() {
            Some(cmd) => (LlmAdapter::new(cmd).rewrite(&skill, &body, &delta)?, true),
            None => (format!("{body}{}", delta.to_markdown()), false),
        };

        // 5. Version bump + lineage.
        let from_skill_version = skill.skill_version.clone();
        let to_skill_version = bump.bump_skill(&from_skill_version);
        let parent = skill.id();
        let commit_ref = chain
            .as_ref()
            .map(|c| format!("{}..{}", c.from_ref, c.to_ref))
            .or_else(|| Git::open(&project_root).ok().and_then(|g| g.head().ok()))
            .unwrap_or_else(|| "unknown".into());

        if !dry_run {
            skill.parent = Some(parent.clone());
            skill.skill_version = to_skill_version.clone();
            skill.verified_app_version = to_app.clone();
            skill.context = new_fp;
            skill.confidence = MIGRATED_CONFIDENCE;
            skill.status = SkillStatus::NeedsValidation;
            skill.mutation_history.push(MutationRecord {
                commit: commit_ref,
                reason: delta.reason(),
                timestamp: Utc::now(),
                from_app: Some(from_app.clone()),
                to_app: Some(to_app.clone()),
            });
            self.registry.save_skill(&skill)?;
            self.registry.save_body(&skill, &new_body)?;
        }

        Ok(MigrationOutcome {
            skill: name.to_string(),
            from_skill_version,
            to_skill_version,
            parent,
            from_app,
            to_app: to_app.clone(),
            delta,
            snapshot_dir,
            llm_used,
            dry_run,
        })
    }

    fn commit_chain(
        &self,
        project_root: &Path,
        from_app: &Version,
        to_app: &Version,
    ) -> Option<CommitChain> {
        let arch = Archaeology::new(project_root).ok()?;
        let from_ref = arch.git().resolve_ref(&from_app.to_string())?;
        let to_ref = arch
            .git()
            .resolve_ref(&to_app.to_string())
            .or_else(|| arch.git().resolve_ref("HEAD"))?;
        arch.analyze_refs(&from_ref, &to_ref).ok()
    }
}

/// Mark a skill verified against the current app version.
pub fn verify(registry: &Registry, name: &str, app_version: &Version) -> Result<Skill> {
    let mut skill = registry.load_skill(name)?;
    skill.last_verified = Some(Utc::now().date_naive());
    skill.confidence = VERIFIED_CONFIDENCE;
    skill.status = SkillStatus::Active;
    skill.verified_app_version = app_version.clone();
    registry.save_skill(&skill)?;
    Ok(skill)
}

/// Optional external rewriter. The command receives a JSON payload on
/// stdin (`{skill, skill_version, old_body, delta}`) and must print the
/// new body on stdout. Off unless `llm_command` is set in the config.
pub struct LlmAdapter<'a> {
    command: &'a str,
}

impl<'a> LlmAdapter<'a> {
    pub fn new(command: &'a str) -> Self {
        Self { command }
    }

    pub fn rewrite(&self, skill: &Skill, old_body: &str, delta: &ContextDelta) -> Result<String> {
        let payload = serde_json::json!({
            "skill": skill.name,
            "skill_version": skill.skill_version.to_string(),
            "old_body": old_body,
            "delta": delta,
        });
        let mut child = Command::new("sh")
            .arg("-c")
            .arg(self.command)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()?;
        child
            .stdin
            .take()
            .expect("stdin was piped")
            .write_all(payload.to_string().as_bytes())?;
        let out = child.wait_with_output()?;
        if !out.status.success() {
            return Err(SkillasticError::Llm(format!(
                "'{}' exited with {}: {}",
                self.command,
                out.status,
                String::from_utf8_lossy(&out.stderr).trim()
            )));
        }
        let body = String::from_utf8_lossy(&out.stdout).into_owned();
        if body.trim().is_empty() {
            return Err(SkillasticError::Llm(format!(
                "'{}' produced an empty body",
                self.command
            )));
        }
        Ok(body)
    }
}

//! Core data model: skills, lineage, decisions, fingerprints.

use chrono::{DateTime, NaiveDate, Utc};
use semver::Version;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fmt;

/// Who can invoke a skill.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SkillInvocation {
    /// Only the human types its name.
    UserInvoked,
    /// The model may reach for it automatically.
    ModelInvoked,
    /// Either the human or the model may invoke it.
    #[default]
    Both,
}

impl fmt::Display for SkillInvocation {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let s = match self {
            Self::UserInvoked => "user_invoked",
            Self::ModelInvoked => "model_invoked",
            Self::Both => "both",
        };
        f.write_str(s)
    }
}

fn default_bucket() -> String {
    "core".into()
}

/// A living skill object with lineage, per the Skillastic spec.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Skill {
    pub name: String,
    pub skill_version: Version,
    /// Semver requirement strings this skill is compatible with,
    /// e.g. `">=2.1.0, <3.0.0"`.
    pub compatible_apps: Vec<String>,
    /// Lineage pointer: `"<name>@<skill_version>"`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub parent: Option<String>,
    pub created: DateTime<Utc>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_verified: Option<NaiveDate>,
    /// 0.0–1.0. Auto-migration sets 0.70; `skillastic verify` sets 0.95.
    pub confidence: f64,
    pub status: SkillStatus,
    /// App version this skill was last verified/migrated against.
    pub verified_app_version: Version,
    #[serde(default)]
    pub mutation_history: Vec<MutationRecord>,
    #[serde(default)]
    pub context: ContextFingerprint,
    /// Path of the instruction body, relative to `.skillastic/skills/`.
    pub body_path: String,
    /// Who can invoke this skill.
    #[serde(default)]
    pub invocation: SkillInvocation,
    /// Other skills this skill depends on.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub requires: Vec<String>,
    /// Bucket this skill belongs to, e.g. `core`, `engineering`, `productivity`.
    #[serde(default = "default_bucket")]
    pub bucket: String,
}

impl Skill {
    pub fn new(
        name: impl Into<String>,
        skill_version: Version,
        compatible_apps: Vec<String>,
        verified_app_version: Version,
    ) -> Self {
        let name = name.into();
        Self {
            body_path: format!("{name}.md"),
            name,
            skill_version,
            compatible_apps,
            parent: None,
            created: Utc::now(),
            last_verified: None,
            confidence: 0.50,
            status: SkillStatus::NeedsValidation,
            verified_app_version,
            mutation_history: Vec::new(),
            context: ContextFingerprint::default(),
            invocation: SkillInvocation::default(),
            requires: Vec::new(),
            bucket: default_bucket(),
        }
    }

    /// Stable identifier used in lineage pointers and snapshot dirs.
    pub fn id(&self) -> String {
        format!("{}@{}", self.name, self.skill_version)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SkillStatus {
    Active,
    NeedsValidation,
    NeedsMigration,
    Incompatible,
}

impl fmt::Display for SkillStatus {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let s = match self {
            Self::Active => "active",
            Self::NeedsValidation => "needs_validation",
            Self::NeedsMigration => "needs_migration",
            Self::Incompatible => "incompatible",
        };
        f.write_str(s)
    }
}

/// One entry in a skill's evolutionary history.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MutationRecord {
    /// Commit SHA or range (`old..new`) that motivated the mutation.
    pub commit: String,
    pub reason: String,
    pub timestamp: DateTime<Utc>,
    /// App version window the mutation bridges.
    pub from_app: Option<Version>,
    pub to_app: Option<Version>,
}

/// Deterministic resolver verdict (spec's compatibility table).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Decision {
    /// App patch update — load the skill.
    Load,
    /// App minor update — load, but flag for validation.
    Validate,
    /// App major update / out of range — run the migration pipeline.
    Migrate,
    /// Dependency change not explained by the bump level, or
    /// unresolvable refs — run deep analysis.
    DeepAnalysis,
    /// No lineage and no git history to migrate from.
    Incompatible,
}

impl fmt::Display for Decision {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let s = match self {
            Self::Load => "load",
            Self::Validate => "validate",
            Self::Migrate => "migrate",
            Self::DeepAnalysis => "deep_analysis",
            Self::Incompatible => "incompatible",
        };
        f.write_str(s)
    }
}

/// One skill's resolution against the current app version.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Resolution {
    pub skill: String,
    pub from_app: Version,
    pub to_app: Version,
    pub decision: Decision,
    pub reason: String,
}

/// Semver distance between two app versions.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VersionDelta {
    Same,
    Patch,
    Minor,
    Major,
    Downgrade,
}

impl VersionDelta {
    pub fn between(from: &Version, to: &Version) -> Self {
        if to == from {
            Self::Same
        } else if to < from {
            Self::Downgrade
        } else if to.major != from.major {
            Self::Major
        } else if to.minor != from.minor {
            Self::Minor
        } else {
            Self::Patch
        }
    }

    /// Bump a skill version by the same level as the app bump.
    pub fn bump_skill(&self, v: &Version) -> Version {
        let mut next = v.clone();
        match self {
            Self::Major => {
                next.major += 1;
                next.minor = 0;
                next.patch = 0;
            }
            Self::Minor => {
                next.minor += 1;
                next.patch = 0;
            }
            // Same/Patch/Downgrade all advance the skill by a patch:
            // the skill changed even if the app barely moved.
            _ => next.patch += 1,
        }
        next.pre = semver::Prerelease::EMPTY;
        next.build = semver::BuildMetadata::EMPTY;
        next
    }
}

/// Snapshot of what a codebase actually is, captured at a point in time.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ContextFingerprint {
    /// Inferred frameworks, e.g. "next.js", "react", "next.js app-router".
    #[serde(default)]
    pub frameworks: Vec<String>,
    /// Build/toolchain markers, e.g. "vite", "webpack", "typescript".
    #[serde(default)]
    pub toolchains: Vec<String>,
    /// Notable top-level directories, e.g. "app", "pages", "src".
    #[serde(default)]
    pub directories: Vec<String>,
    /// Dependency name → version requirement, from package manifests.
    #[serde(default)]
    pub dependencies: BTreeMap<String, String>,
}

impl ContextFingerprint {
    pub fn is_empty(&self) -> bool {
        self.frameworks.is_empty()
            && self.toolchains.is_empty()
            && self.directories.is_empty()
            && self.dependencies.is_empty()
    }
}

/// `.skillastic/config.json`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Config {
    pub app_name: String,
    /// Pinned app version; when absent, auto-detect from manifests/git tags.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub app_version: Option<Version>,
    pub auto_migrate: bool,
    /// Optional external command for LLM-assisted body rewrites.
    /// Receives `{old_body, delta}` JSON on stdin, returns the new body
    /// on stdout. Off (None) by default.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub llm_command: Option<String>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            app_name: "app".into(),
            app_version: None,
            auto_migrate: true,
            llm_command: None,
        }
    }
}

/// `.skillastic/state.json` — daemon bookkeeping.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct DaemonState {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_app_version: Option<Version>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_head: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_check: Option<DateTime<Utc>>,
    /// Recent daemon events (ring buffer, newest last).
    #[serde(default)]
    pub events: Vec<String>,
}

impl DaemonState {
    const MAX_EVENTS: usize = 50;

    pub fn log(&mut self, event: impl Into<String>) {
        self.events.push(event.into());
        if self.events.len() > Self::MAX_EVENTS {
            let excess = self.events.len() - Self::MAX_EVENTS;
            self.events.drain(..excess);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn v(s: &str) -> Version {
        Version::parse(s).unwrap()
    }

    #[test]
    fn version_delta_levels() {
        assert_eq!(
            VersionDelta::between(&v("2.4.1"), &v("2.4.1")),
            VersionDelta::Same
        );
        assert_eq!(
            VersionDelta::between(&v("2.4.1"), &v("2.4.2")),
            VersionDelta::Patch
        );
        assert_eq!(
            VersionDelta::between(&v("2.4.1"), &v("2.5.0")),
            VersionDelta::Minor
        );
        assert_eq!(
            VersionDelta::between(&v("2.4.1"), &v("3.0.0")),
            VersionDelta::Major
        );
        assert_eq!(
            VersionDelta::between(&v("3.0.0"), &v("2.4.1")),
            VersionDelta::Downgrade
        );
    }

    #[test]
    fn skill_bump_follows_app_bump() {
        assert_eq!(VersionDelta::Major.bump_skill(&v("2.4.1")), v("3.0.0"));
        assert_eq!(VersionDelta::Minor.bump_skill(&v("2.4.1")), v("2.5.0"));
        assert_eq!(VersionDelta::Patch.bump_skill(&v("2.4.1")), v("2.4.2"));
    }

    #[test]
    fn skill_json_roundtrip() {
        let mut skill = Skill::new(
            "frontend-react",
            v("2.4.1"),
            vec![">=2.1.0, <3.0.0".into()],
            v("2.4.1"),
        );
        skill.parent = Some("frontend-react@2.3.0".into());
        skill.confidence = 0.94;
        skill.mutation_history.push(MutationRecord {
            commit: "a91f3e".into(),
            reason: "Added vector indexing".into(),
            timestamp: Utc::now(),
            from_app: Some(v("2.3.0")),
            to_app: Some(v("2.4.0")),
        });

        let json = serde_json::to_string_pretty(&skill).unwrap();
        let back: Skill = serde_json::from_str(&json).unwrap();
        assert_eq!(back.id(), "frontend-react@2.4.1");
        assert_eq!(back.parent.as_deref(), Some("frontend-react@2.3.0"));
        assert_eq!(back.mutation_history.len(), 1);
        assert_eq!(back.status, SkillStatus::NeedsValidation);
        assert_eq!(back.invocation, SkillInvocation::Both);
        assert_eq!(back.bucket, "core");
        assert!(back.requires.is_empty());
    }

    #[test]
    fn skill_defaults_for_backward_compatibility() {
        let old = r#"{
            "name": "legacy",
            "skill_version": "1.0.0",
            "compatible_apps": [],
            "created": "2024-01-01T00:00:00Z",
            "confidence": 0.5,
            "status": "needs_validation",
            "verified_app_version": "1.0.0",
            "body_path": "legacy.md"
        }"#;
        let skill: Skill = serde_json::from_str(old).unwrap();
        assert_eq!(skill.invocation, SkillInvocation::Both);
        assert_eq!(skill.bucket, "core");
        assert!(skill.requires.is_empty());
    }

    #[test]
    fn daemon_state_ring_buffer() {
        let mut state = DaemonState::default();
        for i in 0..60 {
            state.log(format!("event {i}"));
        }
        assert_eq!(state.events.len(), DaemonState::MAX_EVENTS);
        assert_eq!(state.events.last().unwrap(), "event 59");
    }
}

//! Multi-repo monitoring: tracks which project roots should have a
//! `skillastic daemon` running, and starts/checks those daemons.
//!
//! Mirrors the "resume" model used by other repo-watching daemons on this
//! machine: a small JSON registry plus a `resume` operation that spawns a
//! detached daemon for every enabled, not-already-running entry. Designed to
//! be triggered by a login (user scope) or boot (system scope) systemd unit
//! installed via `skillastic enroll`.

use crate::error::{Result, SkillasticError};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs;
use std::os::unix::process::CommandExt;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

const IGNORED_DIR_NAMES: &[&str] = &[
    "target",
    "node_modules",
    "dist",
    "build",
    ".next",
    "coverage",
    "__pycache__",
    ".venv",
    "vendor",
];

/// Drop a file with this name in a directory to prune it (and everything
/// below it) from discovery — used by `skillastic register --mandatory`
/// and `skillastic enroll` alike.
pub const IGNORE_MARKER: &str = ".skillasticignore";

/// Where a monitor registry (and its systemd unit) lives.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Scope {
    /// Per-user: started at login, registry under `$XDG_CONFIG_HOME`.
    User,
    /// Whole-machine: started at boot, registry under `/etc`.
    System,
}

impl Scope {
    pub fn registry_path(self) -> Result<PathBuf> {
        Ok(match self {
            Scope::User => user_config_dir()?.join("skillastic/monitored.json"),
            Scope::System => PathBuf::from("/etc/skillastic/monitored.json"),
        })
    }

    /// Where the user's custom scan config lives — a small JSON file with an
    /// `extra_roots` array of additional directories `register --mandatory`
    /// (and `enroll`) should scan besides the home directory.
    pub fn global_config_path(self) -> Result<PathBuf> {
        Ok(match self {
            Scope::User => user_config_dir()?.join("skillastic/config.json"),
            Scope::System => PathBuf::from("/etc/skillastic/config.json"),
        })
    }

    pub fn requires_root(self) -> bool {
        matches!(self, Scope::System)
    }

    pub fn label(self) -> &'static str {
        match self {
            Scope::User => "user",
            Scope::System => "system",
        }
    }
}

/// Default directory to scan when the caller didn't name one: `$HOME` for
/// per-user scope, or `/home` (all users) for system scope.
pub fn default_scan_root(scope: Scope) -> Result<PathBuf> {
    match scope {
        Scope::User => home_dir(),
        Scope::System => Ok(PathBuf::from("/home")),
    }
}

pub fn home_dir() -> Result<PathBuf> {
    std::env::var("HOME")
        .map(PathBuf::from)
        .map_err(|_| SkillasticError::Other("$HOME is not set".into()))
}

fn user_config_dir() -> Result<PathBuf> {
    if let Ok(dir) = std::env::var("XDG_CONFIG_HOME") {
        if !dir.is_empty() {
            return Ok(PathBuf::from(dir));
        }
    }
    Ok(home_dir()?.join(".config"))
}

/// The user's custom scan roots, read from [`Scope::global_config_path`].
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct GlobalConfig {
    #[serde(default)]
    pub extra_roots: Vec<PathBuf>,
}

impl GlobalConfig {
    pub fn load(scope: Scope) -> Result<Self> {
        Self::load_from(&scope.global_config_path()?)
    }

    pub fn load_from(path: &Path) -> Result<Self> {
        if !path.is_file() {
            return Ok(Self::default());
        }
        let raw = fs::read_to_string(path)?;
        Ok(serde_json::from_str(&raw)?)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MonitoredProject {
    pub path: PathBuf,
    #[serde(default = "default_true")]
    pub enabled: bool,
    #[serde(default = "default_interval")]
    pub interval: u64,
}

fn default_true() -> bool {
    true
}

fn default_interval() -> u64 {
    300
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct MonitorRegistry {
    #[serde(default)]
    pub projects: BTreeMap<String, MonitoredProject>,
}

impl MonitorRegistry {
    pub fn load(scope: Scope) -> Result<Self> {
        Self::load_from(&scope.registry_path()?)
    }

    pub fn save(&self, scope: Scope) -> Result<()> {
        self.save_to(&scope.registry_path()?)
    }

    pub fn load_from(path: &Path) -> Result<Self> {
        if !path.is_file() {
            return Ok(Self::default());
        }
        let raw = fs::read_to_string(path)?;
        Ok(serde_json::from_str(&raw)?)
    }

    pub fn save_to(&self, path: &Path) -> Result<()> {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(path, serde_json::to_string_pretty(self)?)?;
        Ok(())
    }

    pub fn upsert(&mut self, path: &Path, interval: u64) {
        let key = key_for(path);
        self.projects
            .entry(key)
            .and_modify(|p| p.interval = interval)
            .or_insert(MonitoredProject {
                path: path.to_path_buf(),
                enabled: true,
                interval,
            });
    }

    pub fn remove(&mut self, path: &Path) -> bool {
        self.projects.remove(&key_for(path)).is_some()
    }

    pub fn contains(&self, path: &Path) -> bool {
        self.projects.contains_key(&key_for(path))
    }

    pub fn set_enabled(&mut self, path: &Path, enabled: bool) -> Result<()> {
        let key = key_for(path);
        let entry = self
            .projects
            .get_mut(&key)
            .ok_or_else(|| SkillasticError::Other(format!("not monitored: {}", path.display())))?;
        entry.enabled = enabled;
        Ok(())
    }
}

fn key_for(path: &Path) -> String {
    path.canonicalize()
        .unwrap_or_else(|_| path.to_path_buf())
        .display()
        .to_string()
}

/// One repo found while scanning for monitoring candidates.
#[derive(Debug, Clone)]
pub struct DiscoveredRepo {
    pub path: PathBuf,
    pub has_skillastic: bool,
}

/// Finds git repos under `roots`, skipping build/dependency directories and
/// any directory containing an [`IGNORE_MARKER`] file (and everything below
/// it). Descends past repos it finds (a dotfiles-style repo at `$HOME` is
/// common and must not swallow every project living underneath it).
pub fn discover_repos(roots: &[PathBuf], max_depth: usize) -> Result<Vec<DiscoveredRepo>> {
    let mut found = Vec::new();
    for root in roots {
        walk(root, 0, max_depth, &mut found);
    }
    found.sort_by(|a: &DiscoveredRepo, b| a.path.cmp(&b.path));
    found.dedup_by(|a, b| a.path == b.path);
    Ok(found)
}

fn walk(dir: &Path, depth: usize, max_depth: usize, found: &mut Vec<DiscoveredRepo>) {
    if depth > max_depth {
        return;
    }
    if dir.join(IGNORE_MARKER).is_file() {
        return; // opted out: skip this directory and everything below it
    }
    if dir.join(".git").is_dir() {
        found.push(DiscoveredRepo {
            path: dir.to_path_buf(),
            has_skillastic: dir.join(".skillastic").is_dir(),
        });
        // Keep descending: a repo (e.g. a dotfiles repo at $HOME) can still
        // have real project repos living underneath it.
    }
    let Ok(entries) = fs::read_dir(dir) else {
        return; // unreadable (permissions, races); skip rather than fail the scan
    };
    for entry in entries.flatten() {
        let Ok(file_type) = entry.file_type() else {
            continue;
        };
        if !file_type.is_dir() {
            continue;
        }
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.starts_with('.') || IGNORED_DIR_NAMES.contains(&name.as_str()) {
            continue;
        }
        walk(&entry.path(), depth + 1, max_depth, found);
    }
}

/// Outcome of trying to (re)start a monitored project's daemon.
#[derive(Debug, Clone, Serialize)]
pub struct ResumeOutcome {
    pub path: PathBuf,
    pub action: ResumeAction,
}

#[derive(Debug, Clone, Serialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum ResumeAction {
    Started { pid: u32 },
    AlreadyRunning { pid: u32 },
    Skipped { reason: String },
}

impl ResumeOutcome {
    pub fn describe(&self) -> String {
        let path = self.path.display();
        match &self.action {
            ResumeAction::Started { pid } => format!("{path}: started (pid {pid})"),
            ResumeAction::AlreadyRunning { pid } => format!("{path}: already running (pid {pid})"),
            ResumeAction::Skipped { reason } => format!("{path}: skipped ({reason})"),
        }
    }
}

/// Starts daemons for every enabled, not-running entry in `scope`'s registry.
pub fn resume(scope: Scope) -> Result<Vec<ResumeOutcome>> {
    let registry = MonitorRegistry::load(scope)?;
    let mut outcomes = Vec::new();
    for project in registry.projects.values() {
        let action = if !project.enabled {
            ResumeAction::Skipped {
                reason: "disabled".into(),
            }
        } else if !project.path.join(".skillastic").is_dir() {
            ResumeAction::Skipped {
                reason: "no .skillastic workspace".into(),
            }
        } else if let Some(pid) = running_daemon_pid(&project.path) {
            ResumeAction::AlreadyRunning { pid }
        } else {
            ResumeAction::Started {
                pid: spawn_daemon(&project.path, project.interval)?,
            }
        };
        outcomes.push(ResumeOutcome {
            path: project.path.clone(),
            action,
        });
    }
    Ok(outcomes)
}

fn pid_file(path: &Path) -> PathBuf {
    path.join(".skillastic/daemon.pid")
}

/// The daemon's pid for `path`, if its pid file names a live process.
pub fn running_daemon_pid(path: &Path) -> Option<u32> {
    let raw = fs::read_to_string(pid_file(path)).ok()?;
    let pid: u32 = raw.trim().parse().ok()?;
    Path::new(&format!("/proc/{pid}")).is_dir().then_some(pid)
}

fn spawn_daemon(path: &Path, interval: u64) -> Result<u32> {
    let exe = std::env::current_exe()?;
    spawn_detached(&exe, &["daemon", "--interval", &interval.to_string()], path)
}

/// Spawns `exe args...` detached, in `path`, recording its pid. Args are
/// passed through generically so tests can point `exe` at a harmless
/// stand-in (e.g. `/bin/sleep`) instead of re-invoking the real daemon loop.
fn spawn_detached(exe: &Path, args: &[&str], path: &Path) -> Result<u32> {
    let skillastic_dir = path.join(".skillastic");
    fs::create_dir_all(&skillastic_dir)?;
    let out = fs::File::create(skillastic_dir.join("daemon.out"))?;
    let err = fs::File::create(skillastic_dir.join("daemon.err"))?;
    let child = Command::new(exe)
        .args(args)
        .current_dir(path)
        .stdin(Stdio::null())
        .stdout(out)
        .stderr(err)
        .process_group(0) // own process group: survives the parent's shell/session
        .spawn()?;
    let pid = child.id();
    fs::write(pid_file(path), pid.to_string())?;
    // Deliberately not `.wait()`-ed: this is meant to outlive the current
    // process. It gets reparented to init and reaped normally on exit.
    drop(child);
    Ok(pid)
}

