    #[test]
    fn discovers_repos_and_flags_skillastic_workspaces() {
        let dir = TempDir::new().unwrap();
        make_git_repo(dir.path(), "alpha", true);
        make_git_repo(dir.path(), "nested/beta", false);
        fs::create_dir_all(dir.path().join("nested/beta/vendor/inner")).unwrap();
        make_git_repo(dir.path(), "nested/beta/vendor/inner", true); // ignored dir, should not appear

        let found = discover_repos(&[dir.path().to_path_buf()], 6).unwrap();
        assert_eq!(found.len(), 2);
        let alpha = found.iter().find(|r| r.path.ends_with("alpha")).unwrap();
        assert!(alpha.has_skillastic);
        let beta = found
            .iter()
            .find(|r| r.path.ends_with("nested/beta"))
            .unwrap();
        assert!(!beta.has_skillastic);
    }

    #[test]
    fn descends_past_an_outer_repo_to_find_nested_ones() {
        // A dotfiles-style repo at $HOME is common; it must not swallow the
        // real project repos that live underneath it.
        let dir = TempDir::new().unwrap();
        make_git_repo(dir.path(), "outer", false);
        make_git_repo(dir.path(), "outer/inner", true);

        let found = discover_repos(&[dir.path().to_path_buf()], 6).unwrap();
        assert_eq!(found.len(), 2);
        assert!(found.iter().any(|r| r.path.ends_with("outer")));
        assert!(found.iter().any(|r| r.path.ends_with("outer/inner")));
    }

    #[test]
    fn ignore_marker_prunes_a_directory_and_everything_below_it() {
        let dir = TempDir::new().unwrap();
        make_git_repo(dir.path(), "kept", false);
        make_git_repo(dir.path(), "skipped", false);
        make_git_repo(dir.path(), "skipped/nested", true);
        fs::write(dir.path().join("skipped").join(IGNORE_MARKER), "").unwrap();

        let found = discover_repos(&[dir.path().to_path_buf()], 6).unwrap();
        assert_eq!(found.len(), 1);
        assert!(found[0].path.ends_with("kept"));
    }

    #[test]
    fn global_config_round_trips_extra_roots() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("config.json");
        assert!(
            GlobalConfig::load_from(&path)
                .unwrap()
                .extra_roots
                .is_empty()
        );

        fs::write(
            &path,
            serde_json::json!({ "extra_roots": ["/srv/projects", "/opt/work"] }).to_string(),
        )
        .unwrap();
        let loaded = GlobalConfig::load_from(&path).unwrap();
        assert_eq!(
            loaded.extra_roots,
            vec![PathBuf::from("/srv/projects"), PathBuf::from("/opt/work")]
        );
    }

    #[test]
    fn registry_round_trips_through_disk() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("monitored.json");
        let mut registry = MonitorRegistry::load_from(&path).unwrap();
        assert!(registry.projects.is_empty());

        registry.upsert(&dir.path().join("proj"), 120);
        registry.save_to(&path).unwrap();

        let reloaded = MonitorRegistry::load_from(&path).unwrap();
        assert_eq!(reloaded.projects.len(), 1);
        let entry = reloaded.projects.values().next().unwrap();
        assert_eq!(entry.interval, 120);
        assert!(entry.enabled);
    }

    #[test]
    fn enable_disable_and_remove_target_the_same_entry() {
        let dir = TempDir::new().unwrap();
        let proj = dir.path().join("proj");
        fs::create_dir_all(&proj).unwrap();
        let mut registry = MonitorRegistry::default();
        registry.upsert(&proj, 60);
        assert!(registry.contains(&proj));

        registry.set_enabled(&proj, false).unwrap();
        assert!(!registry.projects.values().next().unwrap().enabled);

        assert!(registry.remove(&proj));
        assert!(registry.projects.is_empty());
        assert!(!registry.contains(&proj));
    }

    #[test]
    fn set_enabled_on_unknown_path_errors() {
        let dir = TempDir::new().unwrap();
        let mut registry = MonitorRegistry::default();
        assert!(
            registry
                .set_enabled(&dir.path().join("nope"), true)
                .is_err()
        );
    }

    #[test]
    fn spawn_daemon_writes_a_live_pid_file() {
        let dir = TempDir::new().unwrap();
        let proj = dir.path().join("proj");
        fs::create_dir_all(&proj).unwrap();
        // Stand in for the real binary with something that just sleeps, so
        // this test never runs actual daemon logic.
        let pid = spawn_detached(Path::new("/bin/sleep"), &["30"], &proj).unwrap();
        assert!(running_daemon_pid(&proj).is_some());
        // Clean up: don't leave a sleeping process behind.
        let _ = Command::new("kill").arg(pid.to_string()).status();
    }
}

//! `skillastic register`: create (or reuse) a `.skillastic` workspace for
//! one or more projects and index them into the monitor registry so the
//! daemon supervisor picks them up.
//!
//! With `--mandatory`, instead of registering only the given paths, this
//! recursively scans the home directory (or `/home` for system scope) plus
//! any extra roots from the user's global config
//! ([`Scope::global_config_path`]), registering every project it finds.
//! Opt a directory out with a [`monitor::IGNORE_MARKER`] file.

use crate::error::{Result, SkillasticError};
use crate::model::Config;
use crate::monitor::{self, GlobalConfig, MonitorRegistry, Scope};
use crate::registry::Registry;
use serde::Serialize;
use std::path::{Path, PathBuf};

pub struct RegisterOptions {
    /// Explicit project directories (targeted mode), or extra scan roots on
    /// top of the defaults (mandatory mode).
    pub paths: Vec<PathBuf>,
    pub mandatory: bool,
    pub scope: Scope,
    pub interval: u64,
    /// Only used with `mandatory`.
    pub max_depth: usize,
    /// Report what would happen without writing or starting anything.
    pub dry_run: bool,
}

#[derive(Debug, Serialize)]
pub struct RegisterReport {
    pub mandatory: bool,
    pub dry_run: bool,
    /// Projects newly added to the registry.
    pub registered: Vec<String>,
    /// Projects that got a fresh `.skillastic` workspace.
    pub initialized: Vec<String>,
    /// Projects that were already registered (interval refreshed).
    pub already_indexed: Vec<String>,
}

pub fn run(opts: RegisterOptions) -> Result<RegisterReport> {
    if opts.mandatory {
        run_mandatory(&opts)
    } else {
        run_targeted(&opts)
    }
}

fn run_targeted(opts: &RegisterOptions) -> Result<RegisterReport> {
    let targets = if opts.paths.is_empty() {
        vec![std::env::current_dir()?]
    } else {
        opts.paths.clone()
    };
    for path in &targets {
        if !path.is_dir() {
            return Err(SkillasticError::Other(format!(
                "not a directory: {}",
                path.display()
            )));
        }
    }

    let mut registry = load_registry(opts)?;
    let mut registered = Vec::new();
    let mut initialized = Vec::new();
    let mut already_indexed = Vec::new();

    for path in &targets {
        let path = path.canonicalize().unwrap_or_else(|_| path.clone());
        let has_skillastic = path.join(".skillastic").is_dir();
        index_one(
            opts,
            &mut registry,
            &path,
            has_skillastic,
            &mut registered,
            &mut initialized,
            &mut already_indexed,
        )?;
    }

    finish(opts, registry, registered, initialized, already_indexed)
}

fn run_mandatory(opts: &RegisterOptions) -> Result<RegisterReport> {
    let global = GlobalConfig::load(opts.scope).unwrap_or_default();
    let mut roots = vec![monitor::default_scan_root(opts.scope)?];
    roots.extend(global.extra_roots);
    roots.extend(opts.paths.clone());
    roots.sort();
    roots.dedup();

    let discovered = monitor::discover_repos(&roots, opts.max_depth)?;

    let mut registry = load_registry(opts)?;
    let mut registered = Vec::new();
    let mut initialized = Vec::new();
    let mut already_indexed = Vec::new();

    for repo in discovered {
        index_one(
            opts,
            &mut registry,
            &repo.path,
            repo.has_skillastic,
            &mut registered,
            &mut initialized,
            &mut already_indexed,
        )?;
    }

    finish(opts, registry, registered, initialized, already_indexed)
}

fn load_registry(opts: &RegisterOptions) -> Result<MonitorRegistry> {
    if opts.dry_run {
        Ok(MonitorRegistry::default())
    } else {
        MonitorRegistry::load(opts.scope)
    }
}

/// Ensures `path` has a `.skillastic` workspace and is indexed in
/// `registry`, recording the outcome into the report buffers.
fn index_one(
    opts: &RegisterOptions,
    registry: &mut MonitorRegistry,
    path: &Path,
    has_skillastic: bool,
    registered: &mut Vec<String>,
    initialized: &mut Vec<String>,
    already_indexed: &mut Vec<String>,
) -> Result<()> {
    let already = registry.contains(path);
    if !has_skillastic {
        if !opts.dry_run {
            let name = path
                .file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_else(|| "app".into());
            Registry::init(
                path,
                Config {
                    app_name: name,
                    ..Default::default()
                },
            )?;
        }
        initialized.push(path.display().to_string());
    }
    if !opts.dry_run {
        registry.upsert(path, opts.interval);
    }
    if already {
        already_indexed.push(path.display().to_string());
    } else {
        registered.push(path.display().to_string());
    }
    Ok(())
}

fn finish(
    opts: &RegisterOptions,
    registry: MonitorRegistry,
    registered: Vec<String>,
    initialized: Vec<String>,
    already_indexed: Vec<String>,
) -> Result<RegisterReport> {
    if !opts.dry_run {
        registry.save(opts.scope)?;
        monitor::resume(opts.scope)?;
    }
    Ok(RegisterReport {
        mandatory: opts.mandatory,
        dry_run: opts.dry_run,
        registered,
        initialized,
        already_indexed,
    })
}

//! Skill Registry: the on-disk `.skillastic/` workspace.
//!
//! Layout:
//! ```text
//! .skillastic/
//!   config.json                 workspace config
//!   state.json                  daemon state
//!   promoted.json               curated promoted skill names
//!   skills/<bucket>/<name>/     meta.json + body.md (new layout)
//!   skills/<name>.json          legacy skill object
//!   skills/<name>.md            legacy instruction body
//!   snapshots/<name>@<ver>/     frozen skill.json + body.md per migration
//! ```

use crate::error::{Result, SkillasticError};
use crate::model::{
    Config, DaemonState, Decision, Resolution, Skill, SkillInvocation, SkillStatus,
};
use crate::templates;
use semver::Version;
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::{Path, PathBuf};

pub const DIR: &str = ".skillastic";
const SKILLS: &str = "skills";
const SNAPSHOTS: &str = "snapshots";
const CONFIG: &str = "config.json";
const STATE: &str = "state.json";
const PROMOTED: &str = "promoted.json";
pub const BUCKETS: &[&str] = &[
    "core",
    "engineering",
    "productivity",
    "misc",
    "in-progress",
    "deprecated",
];

pub struct Registry {
    root: PathBuf,
}

impl Registry {
    /// Create a fresh workspace. Fails if one already exists.
    pub fn init(project_root: &Path, config: Config) -> Result<Self> {
        let root = project_root.join(DIR);
        if root.exists() {
            return Err(SkillasticError::Other(format!(
                "workspace already exists at {}",
                root.display()
            )));
        }
        fs::create_dir_all(root.join(SKILLS))?;
        for bucket in BUCKETS {
            fs::create_dir_all(root.join(SKILLS).join(bucket))?;
        }
        fs::create_dir_all(root.join(SNAPSHOTS))?;
        let registry = Self { root };
        registry.save_config(&config)?;
        registry.save_state(&DaemonState::default())?;
        registry.save_promoted(&PromotedSet {
            skills: vec!["ask-skillastic".into()],
        })?;
        registry.seed_ask_skillastic()?;
        Ok(registry)
    }

    /// Open an existing workspace.
    pub fn open(project_root: &Path) -> Result<Self> {
        let root = project_root.join(DIR);
        if !root.is_dir() {
            return Err(SkillasticError::NotInitialized(root.display().to_string()));
        }
        Ok(Self { root })
    }

    pub fn exists(project_root: &Path) -> bool {
        project_root.join(DIR).is_dir()
    }

    /// Path to the `.skillastic/` directory.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Path to the project that contains this workspace.
    pub fn project_root(&self) -> PathBuf {
        self.root
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_default()
    }

    // ---- config & state -------------------------------------------------

    pub fn config(&self) -> Result<Config> {
        let raw = fs::read_to_string(self.root.join(CONFIG))?;
        Ok(serde_json::from_str(&raw)?)
    }

    pub fn save_config(&self, config: &Config) -> Result<()> {
        write_atomic(
            &self.root.join(CONFIG),
            &serde_json::to_string_pretty(config)?,
        )
    }

    pub fn state(&self) -> Result<DaemonState> {
        let path = self.root.join(STATE);
        if !path.exists() {
            return Ok(DaemonState::default());
        }
        let raw = fs::read_to_string(path)?;
        Ok(serde_json::from_str(&raw)?)
    }

    pub fn save_state(&self, state: &DaemonState) -> Result<()> {
        write_atomic(
            &self.root.join(STATE),
            &serde_json::to_string_pretty(state)?,
        )
    }

    // ---- promoted set ---------------------------------------------------

    pub fn promoted(&self) -> Result<PromotedSet> {
        let path = self.root.join(PROMOTED);
        if !path.exists() {
            return Ok(PromotedSet::default());
        }
        let raw = fs::read_to_string(path)?;
        Ok(serde_json::from_str(&raw)?)
    }

    pub fn save_promoted(&self, set: &PromotedSet) -> Result<()> {
        write_atomic(
            &self.root.join(PROMOTED),
            &serde_json::to_string_pretty(set)?,
        )
    }

    fn seed_ask_skillastic(&self) -> Result<()> {
        let mut skill = Skill::new(
            "ask-skillastic",
            Version::new(1, 0, 0),
            vec![],
            Version::new(0, 0, 0),
        );
        skill.invocation = SkillInvocation::UserInvoked;
        skill.bucket = "core".into();
        skill.confidence = 1.0;
        skill.status = SkillStatus::Active;
        self.add_skill(&skill, templates::ASK_SKILLASTIC_BODY)
    }

    // ---- skills ----------------------------------------------------------

    /// Register a new skill with its instruction body.
    /// New skills are always written to the bucket layout.
    pub fn add_skill(&self, skill: &Skill, body: &str) -> Result<()> {
        validate_name(&skill.name)?;
        if self.find_skill_path(&skill.name).is_some() {
            return Err(SkillasticError::SkillExists(skill.name.clone()));
        }
        let mut skill = skill.clone();
        skill.body_path = format!("{}/{}/body.md", skill.bucket, skill.name);
        self.save_skill(&skill)?;
        self.save_body(&skill, body)?;
        Ok(())
    }

    /// Upsert a skill's metadata (does not touch the body).
    /// Preserves the skill's existing on-disk location.
    pub fn save_skill(&self, skill: &Skill) -> Result<()> {
        validate_name(&skill.name)?;
        let path = self
            .find_skill_path(&skill.name)
            .unwrap_or_else(|| self.new_skill_path(skill));
        write_atomic(&path, &serde_json::to_string_pretty(skill)?)
    }

    /// Reflect a resolver decision onto the stored skill's status.
    /// `Load` leaves the status alone; unknown skills are skipped.
    pub fn apply_resolution(&self, res: &Resolution) -> Result<()> {
        let new_status = match res.decision {
            Decision::Validate | Decision::DeepAnalysis => Some(SkillStatus::NeedsValidation),
            Decision::Migrate => Some(SkillStatus::NeedsMigration),
            Decision::Incompatible => Some(SkillStatus::Incompatible),
            Decision::Load => None,
        };
        if let Some(status) = new_status {
            if let Ok(mut skill) = self.load_skill(&res.skill) {
                if skill.status != status {
                    skill.status = status;
                    self.save_skill(&skill)?;
                }
            }
        }
        Ok(())
    }

    pub fn load_skill(&self, name: &str) -> Result<Skill> {
        let path = self
            .find_skill_path(name)
            .ok_or_else(|| SkillasticError::SkillNotFound(name.to_string()))?;
        let raw = fs::read_to_string(path)?;
        let mut skill: Skill = serde_json::from_str(&raw)?;
        // Backward compatibility: legacy skills may be missing the new fields.
        if skill.bucket.is_empty() {
            skill.bucket = "core".into();
        }
        if skill.body_path.is_empty() {
            skill.body_path = format!("{name}.md");
        }
        Ok(skill)
    }

    /// All registered skills, sorted by name.
    pub fn list_skills(&self) -> Result<Vec<Skill>> {
        let mut skills = Vec::new();
        let dir = self.root.join(SKILLS);
        if !dir.is_dir() {
            return Ok(skills);
        }

        // New bucket layout.
        for bucket in BUCKETS {
            let bucket_dir = dir.join(bucket);
            if !bucket_dir.is_dir() {
                continue;
            }
            for entry in fs::read_dir(&bucket_dir)? {
                let entry = entry?;
                if !entry.file_type()?.is_dir() {
                    continue;
                }
                let meta = entry.path().join("meta.json");
                if meta.is_file() {
                    let raw = fs::read_to_string(&meta)?;
                    skills.push(serde_json::from_str::<Skill>(&raw)?);
                }
            }
        }

        // Legacy flat layout.
        for entry in fs::read_dir(&dir)? {
            let path = entry?.path();
            if path.extension().and_then(|e| e.to_str()) == Some("json") {
                let raw = fs::read_to_string(&path)?;
                skills.push(serde_json::from_str::<Skill>(&raw)?);
            }
        }

        skills.sort_by(|a, b| a.name.cmp(&b.name));
        Ok(skills)
    }

    pub fn skill_body(&self, skill: &Skill) -> Result<String> {
        Ok(fs::read_to_string(self.body_path(skill))?)
    }

    pub fn save_body(&self, skill: &Skill, body: &str) -> Result<()> {
        write_atomic(&self.body_path(skill), body)
    }

    /// Remove a skill and its body.
    pub fn remove_skill(&self, name: &str) -> Result<()> {
        let path = self
            .find_skill_path(name)
            .ok_or_else(|| SkillasticError::SkillNotFound(name.to_string()))?;
        let skill: Skill = serde_json::from_str(&fs::read_to_string(&path)?)?;
        let body_path = self.body_path(&skill);
        fs::remove_file(&path)?;
        if body_path.exists() {
            fs::remove_file(&body_path)?;
        }
        // Best-effort cleanup of empty bucket skill directory.
        if let Some(parent) = path.parent() {
            let _ = fs::remove_dir(parent);
        }
        Ok(())
    }

    // ---- snapshots --------------------------------------------------------

    /// Freeze the current skill.json + body under `snapshots/<name>@<ver>/`.
    /// Returns the snapshot directory.
    pub fn snapshot(&self, skill: &Skill) -> Result<PathBuf> {
        // Reload from disk so we use the canonical body_path for this workspace layout.
        let skill = self.load_skill(&skill.name)?;
        let dir = self.root.join(SNAPSHOTS).join(skill.id());
        fs::create_dir_all(&dir)?;
        write_atomic(
            &dir.join("skill.json"),
            &serde_json::to_string_pretty(&skill)?,
        )?;
        let body = self.skill_body(&skill).unwrap_or_default();
        write_atomic(&dir.join("body.md"), &body)?;
        Ok(dir)
    }

    /// Load a frozen snapshot by id (`"<name>@<version>"`).
    pub fn load_snapshot(&self, id: &str) -> Result<(Skill, String)> {
        let dir = self.root.join(SNAPSHOTS).join(id);
        if !dir.is_dir() {
            return Err(SkillasticError::Other(format!(
                "no snapshot found for {id}"
            )));
        }
        let skill: Skill = serde_json::from_str(&fs::read_to_string(dir.join("skill.json"))?)?;
        let body = fs::read_to_string(dir.join("body.md")).unwrap_or_default();
        Ok((skill, body))
    }

    /// List snapshot ids for a skill, oldest version first.
    pub fn snapshots_for(&self, name: &str) -> Result<Vec<String>> {
        let mut ids = Vec::new();
        let dir = self.root.join(SNAPSHOTS);
        if dir.is_dir() {
            for entry in fs::read_dir(dir)? {
                let id = entry?.file_name().to_string_lossy().into_owned();
                if id.starts_with(&format!("{name}@")) {
                    ids.push(id);
                }
            }
        }
        ids.sort();
        Ok(ids)
    }

    // ---- bucket READMEs ---------------------------------------------------

    /// Regenerate `.skillastic/skills/<bucket>/README.md` indexes.
    pub fn regenerate_bucket_readmes(&self) -> Result<()> {
        let skills = self.list_skills()?;
        for bucket in BUCKETS {
            let bucket_dir = self.root.join(SKILLS).join(bucket);
            if !bucket_dir.is_dir() {
                continue;
            }
            let mut user_invoked = Vec::new();
            let mut model_invoked = Vec::new();
            let mut both = Vec::new();
            for skill in &skills {
                if skill.bucket == *bucket {
                    match skill.invocation {
                        crate::model::SkillInvocation::UserInvoked => user_invoked.push(skill),
                        crate::model::SkillInvocation::ModelInvoked => model_invoked.push(skill),
                        crate::model::SkillInvocation::Both => both.push(skill),
                    }
                }
            }
            let mut lines = vec![format!("# {bucket} skills"), String::new()];
            if !user_invoked.is_empty() {
                lines.push("## User-invoked".into());
                for skill in &user_invoked {
                    let summary = self
                        .skill_body(skill)
                        .ok()
                        .map(|body| first_line_summary(&body))
                        .unwrap_or_else(|| skill.name.clone());
                    lines.push(format!("- **{}** — {}", skill.name, summary));
                }
                lines.push(String::new());
            }
            if !model_invoked.is_empty() {
                lines.push("## Model-invoked".into());
                for skill in &model_invoked {
                    let summary = self
                        .skill_body(skill)
                        .ok()
                        .map(|body| first_line_summary(&body))
                        .unwrap_or_else(|| skill.name.clone());
                    lines.push(format!("- **{}** — {}", skill.name, summary));
                }
                lines.push(String::new());
            }
            if !both.is_empty() {
                lines.push("## Both".into());
                for skill in &both {
                    let summary = self
                        .skill_body(skill)
                        .ok()
                        .map(|body| first_line_summary(&body))
                        .unwrap_or_else(|| skill.name.clone());
                    lines.push(format!("- **{}** — {}", skill.name, summary));
                }
                lines.push(String::new());
            }
            if user_invoked.is_empty() && model_invoked.is_empty() && both.is_empty() {
                lines.push("No skills in this bucket yet.".into());
                lines.push(String::new());
            }
            write_atomic(&bucket_dir.join("README.md"), &lines.join("\n"))?;
        }
        Ok(())
    }

    // ---- paths ------------------------------------------------------------

    /// Locate an existing skill meta file. Returns `(path, is_legacy)`.
    fn find_skill_path(&self, name: &str) -> Option<PathBuf> {
        // New layout: search all buckets.
        for bucket in BUCKETS {
            let path = self
                .root
                .join(SKILLS)
                .join(bucket)
                .join(name)
                .join("meta.json");
            if path.is_file() {
                return Some(path);
            }
        }
        // Legacy flat layout.
        let legacy = self.root.join(SKILLS).join(format!("{name}.json"));
        if legacy.is_file() {
            return Some(legacy);
        }
        None
    }

    /// Path for a new skill in bucket layout.
    fn new_skill_path(&self, skill: &Skill) -> PathBuf {
        self.root
            .join(SKILLS)
            .join(&skill.bucket)
            .join(&skill.name)
            .join("meta.json")
    }

    fn body_path(&self, skill: &Skill) -> PathBuf {
        self.root.join(SKILLS).join(&skill.body_path)
    }
}

/// Curated set of promoted skill names.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct PromotedSet {
    pub skills: Vec<String>,
}

fn first_line_summary(body: &str) -> String {
    body.lines()
        .map(|line| line.trim())
        .find(|line| !line.is_empty())
        .map(|line| {
            let line = line.trim_start_matches("#").trim();
            if line.len() > 80 {
                format!("{}…", &line[..80])
            } else {
                line.to_string()
            }
        })
        .unwrap_or_default()
}

/// Skill names become filenames; keep them safe.
fn validate_name(name: &str) -> Result<()> {
    let ok = !name.is_empty()
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '-' | '_' | '.'))
        && !name.starts_with('.');
    if ok {
        Ok(())
    } else {
        Err(SkillasticError::Other(format!(
            "invalid skill name '{name}': use ASCII letters, digits, '-', '_', '.'"
        )))
    }
}

/// Write via a temp file + rename so a crash never leaves a torn file.
fn write_atomic(path: &Path, contents: &str) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    let tmp = path.with_extension("tmp");
    fs::write(&tmp, contents)?;
    fs::rename(&tmp, path)?;
    Ok(())
}

