//! Version Resolver: deterministic skill/app compatibility decisions.
//!
//! Decision matrix (from the Skillastic spec):
//!
//! | Situation                                             | Decision      |
//! |-------------------------------------------------------|---------------|
//! | App patch update (in range)                           | Load          |
//! | App minor update (in range)                           | Validate      |
//! | App major update / out of `compatible_apps`           | Migrate       |
//! | Dep change beyond what the bump explains, or downgrade| DeepAnalysis  |
//! | No valid compatibility range on the skill             | Incompatible  |

use crate::archaeology::Archaeology;
use crate::error::{Result, SkillasticError};
use crate::model::{Decision, Resolution, Skill, VersionDelta};
use semver::{Version, VersionReq};
use std::collections::HashSet;

/// Knowledge of dependency movement between the two app versions.
/// `None` = unknown (no git history available).
pub type DepsChanged = Option<bool>;

/// Resolves skills against an app version, computing the dependency-change
/// signal per skill from git archaeology when history is available.
pub struct Resolver<'a> {
    arch: Option<&'a Archaeology>,
    to_ref: Option<String>,
}

impl<'a> Resolver<'a> {
    /// `arch` may be None (project not under git); the resolver then works
    /// purely from semver, with the dependency signal unknown.
    pub fn new(arch: Option<&'a Archaeology>, to_app: &Version) -> Self {
        let to_ref = arch.and_then(|a| {
            a.git()
                .resolve_ref(&to_app.to_string())
                .or_else(|| a.git().resolve_ref("HEAD"))
        });
        Self { arch, to_ref }
    }

    /// Did dependencies move between this skill's verified app version and
    /// the target? None when there is no usable git history.
    pub fn deps_changed_for(&self, from_app: &Version) -> DepsChanged {
        let arch = self.arch?;
        let from_ref = arch.git().resolve_ref(&from_app.to_string())?;
        Some(arch.deps_changed(&from_ref, self.to_ref.as_deref()?))
    }

    pub fn resolve(
        &self,
        skill: &Skill,
        to_app: &Version,
        known_names: &HashSet<String>,
    ) -> Result<Resolution> {
        resolve(
            skill,
            to_app,
            self.deps_changed_for(&skill.verified_app_version),
            Some(known_names),
        )
    }

    pub fn resolve_all(&self, skills: &[Skill], to_app: &Version) -> Result<Vec<Resolution>> {
        let known_names: HashSet<String> = skills.iter().map(|s| s.name.clone()).collect();
        skills
            .iter()
            .map(|s| self.resolve(s, to_app, &known_names))
            .collect()
    }
}

pub fn resolve(
    skill: &Skill,
    to_app: &Version,
    deps_changed: DepsChanged,
    known_names: Option<&HashSet<String>>,
) -> Result<Resolution> {
    let from_app = skill.verified_app_version.clone();
    let delta = VersionDelta::between(&from_app, to_app);

    // Dependency satisfiability check.
    if let Some(names) = known_names {
        if let Some(missing) = skill.requires.iter().find(|r| !names.contains(*r)) {
            return Ok(Resolution {
                skill: skill.name.clone(),
                from_app,
                to_app: to_app.clone(),
                decision: Decision::Incompatible,
                reason: format!("required skill '{missing}' is not registered"),
            });
        }
    }

    let mut saw_valid_req = false;
    let mut in_range = false;
    for raw in &skill.compatible_apps {
        if let Ok(req) = parse_req(raw) {
            saw_valid_req = true;
            if req.matches(to_app) {
                in_range = true;
            }
        }
    }

    let (decision, reason) = if !skill.compatible_apps.is_empty() && !saw_valid_req {
        (
            Decision::Incompatible,
            "no parseable semver range in compatible_apps".to_string(),
        )
    } else if delta == VersionDelta::Downgrade {
        (
            Decision::DeepAnalysis,
            format!("app version moved backwards ({from_app} -> {to_app})"),
        )
    } else if !in_range && saw_valid_req {
        (
            Decision::Migrate,
            format!(
                "app {to_app} is outside compatible range {:?}",
                skill.compatible_apps
            ),
        )
    } else {
        match delta {
            VersionDelta::Same => (Decision::Load, format!("skill verified for app {to_app}")),
            VersionDelta::Patch => match deps_changed {
                Some(true) => (
                    Decision::DeepAnalysis,
                    format!(
                        "dependencies changed on a patch bump ({from_app} -> {to_app}); \
                         deeper analysis required"
                    ),
                ),
                Some(false) => (
                    Decision::Load,
                    format!("patch bump {from_app} -> {to_app}, dependencies unchanged"),
                ),
                None => (
                    Decision::Load,
                    format!("patch bump {from_app} -> {to_app} (dependency state unknown)"),
                ),
            },
            VersionDelta::Minor => (
                Decision::Validate,
                format!("minor bump {from_app} -> {to_app}; skill loads but needs validation"),
            ),
            VersionDelta::Major => (
                Decision::Migrate,
                format!("major bump {from_app} -> {to_app} within compatible range"),
            ),
            VersionDelta::Downgrade => unreachable!("handled above"),
        }
    };

    Ok(Resolution {
        skill: skill.name.clone(),
        from_app,
        to_app: to_app.clone(),
        decision,
        reason,
    })
}

pub fn resolve_all(
    skills: &[Skill],
    to_app: &Version,
    deps_changed: DepsChanged,
) -> Result<Vec<Resolution>> {
    let known_names: HashSet<String> = skills.iter().map(|s| s.name.clone()).collect();
    skills
        .iter()
        .map(|s| resolve(s, to_app, deps_changed, Some(&known_names)))
        .collect()
}

/// Parse a semver requirement. Accepts the spec's space-separated form
/// (`">=2.1.0 <3.0.0"`) in addition to the standard comma form.
pub fn parse_req(raw: &str) -> Result<VersionReq> {
    let trimmed = raw.trim();
    let normalized = if trimmed.contains(',') || !trimmed.contains(' ') {
        trimmed.to_string()
    } else {
        trimmed.split_whitespace().collect::<Vec<_>>().join(", ")
    };
    VersionReq::parse(&normalized)
        .map_err(|e| SkillasticError::VersionReq(raw.to_string(), e.to_string()))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn v(s: &str) -> Version {
        Version::parse(s).unwrap()
    }

    fn skill(range: &str, verified: &str) -> Skill {
        Skill::new("s", v("1.0.0"), vec![range.into()], v(verified))
    }

    fn decide(skill: &Skill, to: &str, deps: DepsChanged) -> Decision {
        resolve(skill, &v(to), deps, None).unwrap().decision
    }

    #[test]
    fn spec_matrix() {
        let s = skill(">=2.1.0, <3.0.0", "2.4.1");
        // same version -> load
        assert_eq!(decide(&s, "2.4.1", None), Decision::Load);
        // patch update -> load
        assert_eq!(decide(&s, "2.4.2", Some(false)), Decision::Load);
        // minor update -> validate
        assert_eq!(decide(&s, "2.5.0", None), Decision::Validate);
        // major update, out of range -> migrate
        assert_eq!(decide(&s, "3.0.0", None), Decision::Migrate);
        // unknown dep change on patch -> deep analysis
        assert_eq!(decide(&s, "2.4.2", Some(true)), Decision::DeepAnalysis);
        // downgrade -> deep analysis
        assert_eq!(decide(&s, "2.3.0", None), Decision::DeepAnalysis);
    }

    #[test]
    fn major_bump_inside_a_spanning_range_migrates() {
        let s = skill(">=2.0.0, <4.0.0", "2.9.0");
        assert_eq!(decide(&s, "3.0.0", None), Decision::Migrate);
    }

    #[test]
    fn garbage_range_is_incompatible() {
        let s = skill("not-a-version", "2.4.1");
        assert_eq!(decide(&s, "2.4.1", None), Decision::Incompatible);
    }

    #[test]
    fn missing_dependency_is_incompatible() {
        let mut s = Skill::new("s", v("1.0.0"), vec![">=2.0.0, <3.0.0".into()], v("2.4.1"));
        s.requires = vec!["missing-dep".into()];
        let known = HashSet::from(["s".into()]);
        let res = resolve(&s, &v("2.4.1"), None, Some(&known)).unwrap();
        assert_eq!(res.decision, Decision::Incompatible);
        assert!(res.reason.contains("missing-dep"));
    }

    #[test]
    fn space_separated_range_parses() {
        let req = parse_req(">=2.1.0 <3.0.0").unwrap();
        assert!(req.matches(&v("2.4.1")));
        assert!(!req.matches(&v("3.0.0")));
        // standard forms still work
        assert!(parse_req("^2.1").unwrap().matches(&v("2.9.9")));
        assert!(parse_req(">=1.0.0, <2.0.0").unwrap().matches(&v("1.5.0")));
    }
}

//! Full-text search over registered skills.

use crate::error::Result;
use crate::registry::Registry;
use serde::Serialize;

#[derive(Debug, Serialize)]
pub struct SearchHit {
    pub name: String,
    pub bucket: String,
    pub invocation: String,
    pub matched_in: Vec<String>,
}

pub fn search(registry: &Registry, query: &str) -> Result<Vec<SearchHit>> {
    let q = query.to_lowercase();
    let skills = registry.list_skills()?;
    let mut hits = Vec::new();

    for skill in skills {
        let mut matched_in = Vec::new();
        if skill.name.to_lowercase().contains(&q) {
            matched_in.push("name".into());
        }
        if skill.bucket.to_lowercase().contains(&q) {
            matched_in.push("bucket".into());
        }
        if skill.invocation.to_string().to_lowercase().contains(&q) {
            matched_in.push("invocation".into());
        }
        if let Ok(body) = registry.skill_body(&skill) {
            if body.to_lowercase().contains(&q) {
                matched_in.push("body".into());
            }
        }
        if skill.requires.iter().any(|r| r.to_lowercase().contains(&q)) {
            matched_in.push("requires".into());
        }

        if !matched_in.is_empty() {
            hits.push(SearchHit {
                name: skill.name,
                bucket: skill.bucket,
                invocation: skill.invocation.to_string(),
                matched_in,
            });
        }
    }

    Ok(hits)
}

pub fn hits_to_table(hits: &[SearchHit]) -> String {
    let mut out = String::from("SKILL           BUCKET        INVOCATION    MATCHED\n");
    out.push_str("--------------- ------------- ------------- ----------------\n");
    for hit in hits {
        out.push_str(&format!(
            "{:<15} {:<13} {:<13} {}\n",
            hit.name,
            hit.bucket,
            hit.invocation,
            hit.matched_in.join(", ")
        ));
    }
    out
}

//! Per-repo setup wizard for Skillastic.
//!
//! Seeds the agent-facing configuration that other commands assume:
//! issue tracker, triage labels, and domain doc layout.

use crate::error::{Result, SkillasticError};
use crate::git::Git;
use crate::registry::Registry;
use crate::templates;
use std::io::{self, Write};
use std::path::Path;

pub struct SetupOptions {
    pub non_interactive: bool,
    pub issue_tracker: Option<String>,
}

pub fn run(registry: &Registry, options: SetupOptions) -> Result<()> {
    let project_root = registry.project_root();
    let agents_dir = registry.root().join("agents");
    std::fs::create_dir_all(&agents_dir)?;

    let provider = if options.non_interactive {
        options
            .issue_tracker
            .clone()
            .unwrap_or_else(|| "github".into())
    } else {
        detect_or_ask_tracker(&project_root)?
    };

    let workflow = tracker_workflow(&provider);
    write_agent_doc(
        &agents_dir.join("issue-tracker.md"),
        &format!(
            "{}\n\n## Provider\n\n{}\n\n## Workflow\n\n{}",
            templates::ISSUE_TRACKER_MD_TEMPLATE
                .lines()
                .next()
                .unwrap_or("# Issue tracker"),
            provider,
            workflow
        ),
    )?;

    write_agent_doc(
        &agents_dir.join("triage-labels.md"),
        templates::TRIAGE_LABELS_MD_TEMPLATE,
    )?;

    write_agent_doc(&agents_dir.join("domain.md"), templates::DOMAIN_MD_TEMPLATE)?;

    // Ensure ADR directory exists.
    std::fs::create_dir_all(registry.root().join("adr"))?;

    Ok(())
}

fn detect_or_ask_tracker(project_root: &Path) -> Result<String> {
    if let Ok(git) = Git::open(project_root) {
        // Best-effort remote detection via git CLI is not exposed here;
        // we fall back to asking.
        let _ = git;
    }

    println!("Issue tracker options:");
    println!("  1. GitHub");
    println!("  2. GitLab");
    println!("  3. Linear");
    println!("  4. Local markdown");
    println!("  5. Other");
    print!("Choose (1-5, default 1): ");
    io::stdout().flush().map_err(SkillasticError::Io)?;

    let mut input = String::new();
    io::stdin()
        .read_line(&mut input)
        .map_err(SkillasticError::Io)?;

    let choice = input.trim();
    let provider = match choice {
        "2" => "gitlab",
        "3" => "linear",
        "4" => "local-markdown",
        "5" => "other",
        _ => "github",
    };

    Ok(provider.into())
}

fn tracker_workflow(provider: &str) -> String {
    match provider {
        "github" => "Use `gh issue create` and `gh issue edit`.".into(),
        "gitlab" => "Use `glab issue create` and `glab issue edit`.".into(),
        "linear" => "Use the Linear web UI or CLI to create and update issues.".into(),
        "local-markdown" => "Write one file per issue under `.skillastic/issues/<id>.md`.".into(),
        _ => "Describe your custom workflow here.".into(),
    }
}

fn write_agent_doc(path: &Path, contents: &str) -> Result<()> {
    if path.exists() {
        println!("Preserving existing {}.", path.display());
        return Ok(());
    }
    std::fs::write(path, contents)?;
    Ok(())
}

use serde_json::Value;
use std::fs;
use std::process::{Command, Output};
use tempfile::TempDir;

fn skillastic(dir: &TempDir, args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_skillastic"))
        .args(args)
        .current_dir(dir.path())
        .output()
        .expect("skillastic binary should run")
}

/// Like `skillastic`, but with `$HOME` (and `$XDG_CONFIG_HOME`, cleared)
/// pointed at a sandbox dir — for commands like `register --mandatory` that
/// otherwise default to scanning the real home directory.
fn skillastic_with_home(dir: &TempDir, home: &std::path::Path, args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_skillastic"))
        .args(args)
        .current_dir(dir.path())
        .env("HOME", home)
        .env_remove("XDG_CONFIG_HOME")
        .output()
        .expect("skillastic binary should run")
}

fn success_json(dir: &TempDir, args: &[&str]) -> Value {
    let output = skillastic(dir, args);
    assert!(
        output.status.success(),
        "command {args:?} failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).expect("stdout should be valid JSON")
}

#[test]
fn help_exposes_the_core_workflow() {
    let dir = TempDir::new().unwrap();
    let output = skillastic(&dir, &["--help"]);
    assert!(output.status.success());

    let stdout = String::from_utf8(output.stdout).unwrap();
    for command in [
        "init",
        "setup",
        "add",
        "remove",
        "list",
        "show",
        "status",
        "capture",
        "audit",
        "migrate",
        "verify",
        "history",
        "promoted",
        "lint",
        "doctor",
        "domain-model",
        "adr",
        "docs",
        "search",
        "enroll",
        "monitor",
        "register",
    ] {
        assert!(stdout.contains(command), "help omitted {command}");
    }
}

/// `enroll --dry-run` must never touch the real machine (no systemd units,
/// no binary installs, no registry writes) — it only reports what it found.
#[test]
fn enroll_dry_run_discovers_without_installing_anything() {
    let dir = TempDir::new().unwrap();
    let with_workspace = dir.path().join("has-skillastic");
    fs::create_dir_all(with_workspace.join(".git")).unwrap();
    fs::create_dir_all(with_workspace.join(".skillastic")).unwrap();
    let without_workspace = dir.path().join("plain-git");
    fs::create_dir_all(without_workspace.join(".git")).unwrap();

    let report = success_json(
        &dir,
        &[
            "enroll",
            "--dry-run",
            "--root",
            dir.path().to_str().unwrap(),
            "--json",
        ],
    );
    assert_eq!(report["dry_run"], true);
    assert_eq!(report["scope"], "user");
    assert!(report["binary_path"].is_null());
    assert!(report["unit_path"].is_null());

    let enrolled = report["enrolled"].as_array().unwrap();
    assert!(
        enrolled
            .iter()
            .any(|p| p.as_str().unwrap().ends_with("has-skillastic"))
    );

    let skipped = report["skipped_no_workspace"].as_array().unwrap();
    assert!(
        skipped
            .iter()
            .any(|p| p.as_str().unwrap().ends_with("plain-git"))
    );
    assert!(
        !enrolled
            .iter()
            .any(|p| p.as_str().unwrap().ends_with("plain-git"))
    );

    // Dry run: no side effects anywhere, including on the discovered repo.
    assert!(!without_workspace.join(".skillastic").exists());
}

