/// `register --mandatory --dry-run` scans the home directory like `enroll`
/// does, and must respect a `.skillasticignore` marker. `$HOME` is pointed
/// at a sandbox dir so this never scans the real machine's home directory.
#[test]
fn register_mandatory_dry_run_respects_ignore_marker() {
    let dir = TempDir::new().unwrap();
    let kept = dir.path().join("kept");
    fs::create_dir_all(kept.join(".git")).unwrap();
    let skipped = dir.path().join("skipped");
    fs::create_dir_all(skipped.join(".git")).unwrap();
    fs::write(skipped.join(".skillasticignore"), "").unwrap();

    let output = skillastic_with_home(
        &dir,
        dir.path(),
        &["register", "--mandatory", "--dry-run", "--json"],
    );
    assert!(
        output.status.success(),
        "register --mandatory failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let report: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(report["mandatory"], true);
    let registered = report["registered"].as_array().unwrap();
    assert!(
        registered
            .iter()
            .any(|p| p.as_str().unwrap().ends_with("kept"))
    );
    assert!(
        !registered
            .iter()
            .any(|p| p.as_str().unwrap().ends_with("skipped"))
    );
}

#[test]
fn json_lifecycle_round_trip() {
    let dir = TempDir::new().unwrap();

    let initialized = success_json(
        &dir,
        &[
            "init",
            "--app-name",
            "demo",
            "--app-version",
            "1.2.3",
            "--json",
        ],
    );
    assert_eq!(initialized["app_name"], "demo");

    let added = success_json(
        &dir,
        &[
            "add",
            "frontend",
            "--version",
            "1.0.0",
            "--compatible",
            ">=1.0.0, <2.0.0",
            "--verify",
            "--app-version",
            "1.2.3",
            "--json",
        ],
    );
    assert_eq!(added["name"], "frontend");
    assert_eq!(added["status"], "active");
    assert_eq!(added["verified_app_version"], "1.2.3");

    let listed = success_json(&dir, &["list", "--json"]);
    // ask-skillastic is seeded on init, plus the skill we added.
    assert_eq!(listed.as_array().unwrap().len(), 2);
    let frontend = listed
        .as_array()
        .unwrap()
        .iter()
        .find(|s| s["name"] == "frontend")
        .expect("frontend skill should be listed");
    assert_eq!(frontend["status"], "active");

    let status = success_json(&dir, &["status", "--app-version", "1.2.3", "--json"]);
    assert_eq!(status["app_version"], "1.2.3");
    let frontend_resolution = status["resolutions"]
        .as_array()
        .unwrap()
        .iter()
        .find(|r| r["skill"] == "frontend")
        .expect("frontend should have a resolution");
    assert_eq!(frontend_resolution["decision"], "load");

    let history = success_json(&dir, &["history", "frontend", "--json"]);
    assert_eq!(history.as_array().unwrap().len(), 1);
    assert_eq!(history[0]["name"], "frontend");

    let events = success_json(&dir, &["events", "--json"]);
    assert_eq!(events, Value::Array(Vec::new()));
}

